import * as THREE from 'three';
import { seededRandom, clamp } from './utils.js';

function canvas(w, h = w) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return c;
}

function tex(c, repeatX = 1, repeatY = 1, srgb = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeatX, repeatY);
  t.anisotropy = 8;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.needsUpdate = true;
  return t;
}

function noiseOverlay(ctx, w, h, rng, amount, alpha = 0.5) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rng() - 0.5) * amount;
    d[i] = clamp(d[i] + n, 0, 255);
    d[i + 1] = clamp(d[i + 1] + n, 0, 255);
    d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  ctx.putImageData(img, 0, 0);
}

function normalMapFrom(source, strength = 2.2) {
  const w = source.width, h = source.height;
  const sctx = source.getContext('2d');
  const src = sctx.getImageData(0, 0, w, h).data;
  const out = canvas(w, h);
  const octx = out.getContext('2d');
  const img = octx.createImageData(w, h);
  const d = img.data;
  const lum = (x, y) => {
    x = (x + w) % w; y = (y + h) % h;
    const i = (y * w + x) * 4;
    return (src[i] * 0.299 + src[i + 1] * 0.587 + src[i + 2] * 0.114) / 255;
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const dx = (lum(x + 1, y) - lum(x - 1, y)) * strength;
      const dy = (lum(x, y + 1) - lum(x, y - 1)) * strength;
      const len = Math.hypot(dx, dy, 1);
      const i = (y * w + x) * 4;
      d[i] = ((-dx / len) * 0.5 + 0.5) * 255;
      d[i + 1] = ((dy / len) * 0.5 + 0.5) * 255;
      d[i + 2] = ((1 / len) * 0.5 + 0.5) * 255;
      d[i + 3] = 255;
    }
  }
  octx.putImageData(img, 0, 0);
  return out;
}

function splotches(ctx, w, h, rng, count, colors, radiusMin, radiusMax, alpha = 0.2) {
  for (let i = 0; i < count; i++) {
    const x = rng() * w, y = rng() * h;
    const r = radiusMin + rng() * (radiusMax - radiusMin);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    const col = colors[Math.floor(rng() * colors.length)];
    g.addColorStop(0, `rgba(${col[0]},${col[1]},${col[2]},${alpha})`);
    g.addColorStop(0.55, `rgba(${col[0]},${col[1]},${col[2]},${alpha * 0.45})`);
    g.addColorStop(1, `rgba(${col[0]},${col[1]},${col[2]},0)`);
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
}

function cracks(ctx, w, h, rng, count, color, width = 1.2) {
  ctx.strokeStyle = color;
  ctx.lineCap = 'round';
  for (let i = 0; i < count; i++) {
    let x = rng() * w, y = rng() * h;
    let angle = rng() * Math.PI * 2;
    ctx.lineWidth = width * (0.4 + rng() * 0.9);
    ctx.beginPath();
    ctx.moveTo(x, y);
    const steps = 8 + Math.floor(rng() * 18);
    for (let s = 0; s < steps; s++) {
      angle += (rng() - 0.5) * 0.9;
      x += Math.cos(angle) * (4 + rng() * 11);
      y += Math.sin(angle) * (4 + rng() * 11);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

// ---------------------------------------------------------------- concrete
export function concreteTexture(seed = 1, size = 512) {
  const rng = seededRandom(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#615c54';
  ctx.fillRect(0, 0, size, size);
  splotches(ctx, size, size, rng, 46, [[40, 38, 34], [124, 118, 106], [76, 72, 64], [150, 140, 120]], size * 0.02, size * 0.17, 0.24);
  // panel seams
  ctx.strokeStyle = 'rgba(28,27,25,.5)';
  ctx.lineWidth = 2;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo((i * size) / 4, 0); ctx.lineTo((i * size) / 4, size); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, (i * size) / 4); ctx.lineTo(size, (i * size) / 4); ctx.stroke();
  }
  cracks(ctx, size, size, rng, 22, 'rgba(34,32,29,.55)', 1.1);
  noiseOverlay(ctx, size, size, rng, 28);
  // pitting
  for (let i = 0; i < 900; i++) {
    ctx.fillStyle = rng() > 0.5 ? 'rgba(30,28,25,.35)' : 'rgba(170,162,145,.22)';
    ctx.fillRect(rng() * size, rng() * size, 1 + rng() * 2, 1 + rng() * 2);
  }
  return c;
}

// -------------------------------------------------------------------- sand
export function sandTexture(seed = 2, size = 512) {
  const rng = seededRandom(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#736349';
  ctx.fillRect(0, 0, size, size);
  splotches(ctx, size, size, rng, 40, [[56, 48, 34], [139, 120, 87], [92, 79, 57]], size * 0.03, size * 0.2, 0.2);
  // wind ripples
  for (let i = 0; i < 90; i++) {
    const y = rng() * size;
    ctx.strokeStyle = `rgba(${rng() > 0.5 ? '170,151,112' : '73,63,46'},${0.08 + rng() * 0.1})`;
    ctx.lineWidth = 1 + rng() * 2;
    ctx.beginPath();
    for (let x = 0; x <= size; x += 12) {
      const yy = y + Math.sin(x * 0.025 + i) * (2 + rng() * 4);
      if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
    }
    ctx.stroke();
  }
  noiseOverlay(ctx, size, size, rng, 34);
  for (let i = 0; i < 700; i++) {
    ctx.fillStyle = rng() > 0.5 ? 'rgba(40,35,26,.4)' : 'rgba(190,172,133,.3)';
    const r = 0.5 + rng() * 1.8;
    ctx.beginPath(); ctx.arc(rng() * size, rng() * size, r, 0, Math.PI * 2); ctx.fill();
  }
  return c;
}

// ------------------------------------------------------------------- metal
export function metalTexture(seed = 3, size = 512, color = [72, 78, 82], corrugated = false) {
  const rng = seededRandom(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = `rgb(${color[0]},${color[1]},${color[2]})`;
  ctx.fillRect(0, 0, size, size);
  if (corrugated) {
    const period = size / 24;
    for (let x = 0; x < size; x++) {
      const v = Math.sin((x / period) * Math.PI * 2);
      const shade = Math.round(v * 17);
      ctx.fillStyle = `rgba(${clamp(color[0] + shade, 0, 255)},${clamp(color[1] + shade, 0, 255)},${clamp(color[2] + shade, 0, 255)},.9)`;
      ctx.fillRect(x, 0, 1, size);
    }
  }
  splotches(ctx, size, size, rng, 34, [[30, 24, 20], [120, 60, 30], [150, 145, 130]], size * 0.02, size * 0.14, 0.18);
  // rust streaks
  for (let i = 0; i < 26; i++) {
    const x = rng() * size, y = rng() * size * 0.7;
    const w = 2 + rng() * 8, h = 20 + rng() * 110;
    const g = ctx.createLinearGradient(0, y, 0, y + h);
    g.addColorStop(0, 'rgba(120,55,24,.34)');
    g.addColorStop(1, 'rgba(120,55,24,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x, y, w, h);
  }
  // scratches
  for (let i = 0; i < 70; i++) {
    ctx.strokeStyle = `rgba(${rng() > 0.5 ? '200,200,190' : '20,22,22'},${0.06 + rng() * 0.12})`;
    ctx.lineWidth = 0.6 + rng();
    const x = rng() * size, y = rng() * size;
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (rng() - 0.5) * 90, y + (rng() - 0.5) * 16); ctx.stroke();
  }
  // rivets
  for (let i = 0; i < 40; i++) {
    ctx.fillStyle = 'rgba(20,22,22,.4)';
    ctx.beginPath(); ctx.arc(rng() * size, rng() * size, 1.6, 0, Math.PI * 2); ctx.fill();
  }
  noiseOverlay(ctx, size, size, rng, 20);
  return c;
}

// -------------------------------------------------------------------- wood
export function woodTexture(seed = 4, size = 256) {
  const rng = seededRandom(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#6b4c2c';
  ctx.fillRect(0, 0, size, size);
  for (let p = 0; p < 6; p++) {
    const x0 = (p * size) / 6;
    ctx.fillStyle = `rgba(${90 + rng() * 30},${60 + rng() * 22},${30 + rng() * 16},.55)`;
    ctx.fillRect(x0 + 1, 0, size / 6 - 2, size);
    ctx.strokeStyle = 'rgba(35,22,12,.5)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x0, 0); ctx.lineTo(x0, size); ctx.stroke();
  }
  for (let i = 0; i < 120; i++) {
    ctx.strokeStyle = `rgba(${rng() > 0.5 ? '40,26,14' : '140,100,60'},${0.05 + rng() * 0.12})`;
    ctx.lineWidth = 0.7 + rng() * 1.6;
    const y = rng() * size;
    ctx.beginPath();
    for (let x = 0; x <= size; x += 8) {
      const yy = y + Math.sin(x * 0.04 + i) * 2;
      if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
    }
    ctx.stroke();
  }
  noiseOverlay(ctx, size, size, rng, 24);
  return c;
}

// --------------------------------------------------------- warning stripes
export function warningTexture(size = 256) {
  const rng = seededRandom(9);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#17181a';
  ctx.fillRect(0, 0, size, size);
  ctx.save();
  ctx.translate(size / 2, size / 2);
  ctx.rotate(-Math.PI / 4);
  const step = size / 7;
  for (let x = -size * 2; x < size * 2; x += step * 2) {
    ctx.fillStyle = '#d9a01c';
    ctx.fillRect(x, -size * 2, step, size * 4);
  }
  ctx.restore();
  splotches(ctx, size, size, rng, 20, [[30, 28, 24], [100, 80, 40]], 4, 30, 0.24);
  for (let i = 0; i < 220; i++) {
    ctx.fillStyle = `rgba(${rng() > 0.5 ? '20,20,20' : '120,110,90'},${0.1 + rng() * 0.25})`;
    ctx.fillRect(rng() * size, rng() * size, 1 + rng() * 2, 1 + rng() * 2);
  }
  return c;
}

// -------------------------------------------------------------------- signs
export function signTexture(title, sub = '', opts = {}) {
  const w = 1024, h = 256;
  const c = canvas(w, h);
  const ctx = c.getContext('2d');
  const bg = opts.bg || 'rgba(12,14,15,0.92)';
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = opts.border || 'rgba(255,176,46,0.55)';
  ctx.lineWidth = 6;
  ctx.strokeRect(10, 10, w - 20, h - 20);
  ctx.fillStyle = opts.color || '#e9e3d2';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `700 ${opts.titleSize || 104}px "Arial Narrow", Impact, sans-serif`;
  ctx.fillText(title, w / 2, sub ? h / 2 - 24 : h / 2);
  if (sub) {
    ctx.fillStyle = opts.subColor || '#ffb02e';
    ctx.font = '400 30px "Courier New", monospace';
    ctx.letterSpacing = '8px';
    ctx.fillText(sub, w / 2, h / 2 + 62);
  }
  // wear
  const rng = seededRandom(title.length * 77 + 13);
  for (let i = 0; i < 280; i++) {
    ctx.fillStyle = `rgba(${rng() > 0.5 ? '10,10,10' : '180,170,150'},${0.04 + rng() * 0.16})`;
    ctx.fillRect(rng() * w, rng() * h, 1 + rng() * 3, 1 + rng() * 3);
  }
  return c;
}

// --------------------------------------------------------------- sprites
export function bulletHoleTexture(size = 128) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(0,0,0,0.95)');
  g.addColorStop(0.18, 'rgba(10,9,8,0.9)');
  g.addColorStop(0.42, 'rgba(30,28,25,0.55)');
  g.addColorStop(1, 'rgba(40,38,34,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const rng = seededRandom(42);
  ctx.strokeStyle = 'rgba(22,20,18,.55)';
  for (let i = 0; i < 9; i++) {
    let a = rng() * Math.PI * 2;
    let x = size / 2, y = size / 2;
    ctx.lineWidth = 0.6 + rng() * 1.2;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let s = 0; s < 5; s++) {
      a += (rng() - 0.5) * 0.8;
      x += Math.cos(a) * (4 + rng() * 7);
      y += Math.sin(a) * (4 + rng() * 7);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  return c;
}

export function flashTexture(size = 128) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.translate(size / 2, size / 2);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, size / 2);
  g.addColorStop(0, 'rgba(255,255,240,1)');
  g.addColorStop(0.18, 'rgba(255,220,120,0.95)');
  g.addColorStop(0.45, 'rgba(255,140,30,0.35)');
  g.addColorStop(1, 'rgba(255,90,10,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  const spikes = 9;
  for (let i = 0; i < spikes * 2; i++) {
    const a = (i / (spikes * 2)) * Math.PI * 2;
    const r = i % 2 === 0 ? size * 0.5 : size * 0.16;
    const x = Math.cos(a) * r, y = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,.95)';
  ctx.beginPath(); ctx.arc(0, 0, size * 0.09, 0, Math.PI * 2); ctx.fill();
  return c;
}

export function glowTexture(size = 128, color = [255, 170, 70]) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, `rgba(${color[0]},${color[1]},${color[2]},0.9)`);
  g.addColorStop(0.28, `rgba(${color[0]},${color[1]},${color[2]},0.36)`);
  g.addColorStop(1, `rgba(${color[0]},${color[1]},${color[2]},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return c;
}

export function smokeTexture(size = 128) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const rng = seededRandom(15);
  for (let i = 0; i < 22; i++) {
    const x = size / 2 + (rng() - 0.5) * size * 0.5;
    const y = size / 2 + (rng() - 0.5) * size * 0.5;
    const r = size * (0.12 + rng() * 0.22);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(210,208,200,${0.06 + rng() * 0.07})`);
    g.addColorStop(1, 'rgba(180,178,170,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  return c;
}

// ------------------------------------------------------------- environment
export function skyEquirectTexture(w = 1024, h = 512) {
  const c = canvas(w, h);
  const ctx = c.getContext('2d');
  const rng = seededRandom(31);
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, '#071321');
  g.addColorStop(0.32, '#1b3348');
  g.addColorStop(0.52, '#7b6c74');
  g.addColorStop(0.62, '#e09a5e');
  g.addColorStop(0.7, '#b9703f');
  g.addColorStop(0.8, '#3d3733');
  g.addColorStop(1, '#171512');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  // sun glow
  const sx = w * 0.72, sy = h * 0.64;
  const sg = ctx.createRadialGradient(sx, sy, 0, sx, sy, w * 0.23);
  sg.addColorStop(0, 'rgba(255,238,190,.95)');
  sg.addColorStop(0.04, 'rgba(255,214,140,.9)');
  sg.addColorStop(0.22, 'rgba(255,150,70,.34)');
  sg.addColorStop(1, 'rgba(255,120,50,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = 'rgba(255,248,225,.98)';
  ctx.beginPath(); ctx.arc(sx, sy, w * 0.018, 0, Math.PI * 2); ctx.fill();
  // clouds
  for (let i = 0; i < 34; i++) {
    const x = rng() * w;
    const y = h * (0.18 + rng() * 0.34);
    const rx = w * (0.04 + rng() * 0.13);
    const ry = h * (0.012 + rng() * 0.035);
    const cg = ctx.createRadialGradient(x, y, 0, x, y, rx);
    const dark = 40 + rng() * 35;
    cg.addColorStop(0, `rgba(${dark + 30},${dark + 22},${dark + 20},${0.2 + rng() * 0.25})`);
    cg.addColorStop(1, `rgba(${dark},${dark},${dark},0)`);
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(1, ry / rx);
    ctx.translate(-x, -y);
    ctx.fillStyle = cg;
    ctx.beginPath(); ctx.arc(x, y, rx, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
  // ground haze
  const hg = ctx.createLinearGradient(0, h * 0.68, 0, h);
  hg.addColorStop(0, 'rgba(200,130,80,0)');
  hg.addColorStop(1, 'rgba(10,10,10,1)');
  ctx.fillStyle = hg;
  ctx.fillRect(0, h * 0.68, w, h * 0.32);
  return c;
}

export function createTextureSet() {
  const concreteCanvas = concreteTexture(1);
  const sandCanvas = sandTexture(2);
  const metalCanvas = metalTexture(3, 512, [74, 80, 84], false);
  const containerCanvas = metalTexture(5, 512, [78, 88, 82], true);
  const woodCanvas = woodTexture(4);
  const warningCanvas = warningTexture(256);

  const concreteNormal = normalMapFrom(concreteCanvas, 2.0);
  const metalNormal = normalMapFrom(metalCanvas, 1.6);
  const sandNormal = normalMapFrom(sandCanvas, 1.2);

  return {
    concrete: tex(concreteCanvas, 1, 1),
    concreteWall: tex(concreteCanvas, 4, 2),
    concreteNormal: tex(concreteNormal, 1, 1, false),
    concreteWallNormal: tex(concreteNormal, 4, 2, false),
    sand: tex(sandCanvas, 24, 24),
    sandNormal: tex(sandNormal, 24, 24, false),
    metal: tex(metalCanvas, 1, 1),
    metalNormal: tex(metalNormal, 1, 1, false),
    container: tex(containerCanvas, 2, 1),
    containerNormal: tex(metalNormal, 2, 1, false),
    wood: tex(woodCanvas, 1, 1),
    warning: tex(warningCanvas, 1, 1),
    bulletHole: tex(bulletHoleTexture(), 1, 1),
    flash: tex(flashTexture(), 1, 1),
    glow: tex(glowTexture(128, [255, 160, 60]), 1, 1),
    glowCyan: tex(glowTexture(128, [90, 220, 255]), 1, 1),
    smoke: tex(smokeTexture(), 1, 1),
    sky: tex(skyEquirectTexture(), 1, 1),
  };
}

import * as THREE from 'three';
import { seededRandom, clamp, rand, TAU } from './utils.js';
import { signTexture } from './textures.js';

const UP = new THREE.Vector3(0, 1, 0);
const _v = new THREE.Vector3();

function rep(t, x, y) {
  const c = t.clone();
  c.needsUpdate = true;
  c.wrapS = c.wrapT = THREE.RepeatWrapping;
  c.repeat.set(x, y);
  return c;
}

function boxGeo(w, h, d) { return new THREE.BoxGeometry(w, h, d); }

export function createWorld(scene, renderer, T, quality = 'high') {
  const high = quality === 'high';
  const med = quality !== 'low';
  const colliders = [];
  const occluders = [];
  const barrels = [];
  const spawnPoints = [
    { x: 0, z: -20, yaw: Math.PI },
    { x: -20, z: -18, yaw: Math.PI * 0.75 },
    { x: 21, z: -16, yaw: -Math.PI * 0.75 },
    { x: -32, z: 2, yaw: Math.PI * 0.5 },
    { x: 33, z: 2, yaw: -Math.PI * 0.5 },
    { x: -20, z: 24, yaw: Math.PI * 0.2 },
    { x: 22, z: 24, yaw: -Math.PI * 0.2 },
    { x: 0, z: 38, yaw: 0 },
  ];
  const pickupPoints = [
    { x: -6, z: 12 }, { x: 7, z: 8 }, { x: -14, z: -6 },
    { x: 14, z: -10 }, { x: 0, z: -20 }, { x: 18, z: 18 },
  ];

  const envSource = T.sky.clone();
  envSource.mapping = THREE.EquirectangularReflectionMapping;
  envSource.needsUpdate = true;
  const pmrem = new THREE.PMREMGenerator(renderer);
  const envRT = pmrem.fromEquirectangular(envSource);
  scene.environment = envRT.texture;
  scene.environmentIntensity = 0.75;
  pmrem.dispose();
  envSource.dispose();

  scene.fog = new THREE.FogExp2(0x5c5147, 0.0095);

  // ------------------------------------------------------------- materials
  const M = {};
  M.concrete = new THREE.MeshStandardMaterial({
    map: rep(T.concrete, 4, 2), normalMap: rep(T.concreteNormal, 4, 2),
    normalScale: new THREE.Vector2(0.75, 0.75), roughness: 0.96, metalness: 0.02,
    color: 0xb5ada0,
  });
  M.concreteSmall = new THREE.MeshStandardMaterial({
    map: rep(T.concrete, 1.6, 1), normalMap: rep(T.concreteNormal, 1.6, 1),
    normalScale: new THREE.Vector2(0.6, 0.6), roughness: 0.95, metalness: 0.02, color: 0xaaa296,
  });
  M.ground = new THREE.MeshStandardMaterial({
    map: T.sand, normalMap: T.sandNormal, normalScale: new THREE.Vector2(0.8, 0.8),
    roughness: 1, metalness: 0, color: 0x9b8a6c,
  });
  M.metal = new THREE.MeshStandardMaterial({
    map: rep(T.metal, 1, 1), normalMap: rep(T.metalNormal, 1, 1),
    normalScale: new THREE.Vector2(0.7, 0.7), roughness: 0.48, metalness: 0.72, color: 0x8b9296,
  });
  M.darkMetal = new THREE.MeshStandardMaterial({ color: 0x272c2f, roughness: 0.42, metalness: 0.82 });
  M.gunmetal = new THREE.MeshStandardMaterial({ color: 0x191d20, roughness: 0.35, metalness: 0.9 });
  M.rust = new THREE.MeshStandardMaterial({ color: 0x6b3c26, roughness: 0.85, metalness: 0.35 });
  M.wood = new THREE.MeshStandardMaterial({ map: rep(T.wood, 1, 1), roughness: 0.9, metalness: 0.02, color: 0xa88a64 });
  M.woodDark = new THREE.MeshStandardMaterial({ map: rep(T.wood, 1, 1), roughness: 0.92, metalness: 0.02, color: 0x6f573d });
  M.warning = new THREE.MeshStandardMaterial({ map: T.warning, roughness: 0.8, metalness: 0.1 });
  M.sandbag = new THREE.MeshStandardMaterial({ map: rep(T.sand, 2, 1), roughness: 1, metalness: 0, color: 0xa2916f });
  M.rubber = new THREE.MeshStandardMaterial({ color: 0x111315, roughness: 0.92, metalness: 0.02 });
  M.olive = new THREE.MeshStandardMaterial({ color: 0x4a5140, roughness: 0.72, metalness: 0.25 });
  M.containerRed = new THREE.MeshStandardMaterial({ map: T.container, normalMap: T.containerNormal, color: 0x9a4d38, roughness: 0.62, metalness: 0.5 });
  M.containerGreen = new THREE.MeshStandardMaterial({ map: T.container, normalMap: T.containerNormal, color: 0x5e6f56, roughness: 0.66, metalness: 0.45 });
  M.containerBlue = new THREE.MeshStandardMaterial({ map: T.container, normalMap: T.containerNormal, color: 0x4a6475, roughness: 0.64, metalness: 0.48 });
  M.glass = new THREE.MeshStandardMaterial({ color: 0x16303c, emissive: 0x2f7f93, emissiveIntensity: 0.9, roughness: 0.15, metalness: 0.4 });
  M.lamp = new THREE.MeshStandardMaterial({ color: 0xfff1cc, emissive: 0xffd28a, emissiveIntensity: 4.5, roughness: 0.4 });
  M.redLamp = new THREE.MeshStandardMaterial({ color: 0x3a0705, emissive: 0xff1a10, emissiveIntensity: 5, roughness: 0.4 });
  M.cyanLamp = new THREE.MeshStandardMaterial({ color: 0x06222a, emissive: 0x5ce4ff, emissiveIntensity: 4, roughness: 0.4 });
  M.mountain = new THREE.MeshStandardMaterial({ color: 0x39332d, roughness: 1, metalness: 0, flatShading: true });
  M.rock = new THREE.MeshStandardMaterial({ color: 0x4c4439, roughness: 1, metalness: 0, flatShading: true });
  M.coneLight = new THREE.MeshBasicMaterial({
    color: 0xffc070, transparent: true, opacity: 0.035, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide, fog: false,
  });
  M.redCone = new THREE.MeshBasicMaterial({
    color: 0xff3a20, transparent: true, opacity: 0.05, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide, fog: false,
  });

  const root = new THREE.Group();
  scene.add(root);

  function addBox(w, h, d, mat, x, y, z, opts = {}) {
    const m = new THREE.Mesh(boxGeo(w, h, d), mat);
    m.position.set(x, y, z);
    if (opts.rx) m.rotation.x = opts.rx;
    if (opts.ry) m.rotation.y = opts.ry;
    if (opts.rz) m.rotation.z = opts.rz;
    m.castShadow = opts.cast !== false;
    m.receiveShadow = opts.receive !== false;
    (opts.parent || root).add(m);
    return m;
  }

  function addCollider(x, z, w, d, h = 6, y0 = 0) {
    const c = { minX: x - w / 2, maxX: x + w / 2, minZ: z - d / 2, maxZ: z + d / 2, minY: y0, maxY: y0 + h };
    colliders.push(c);
    occluders.push(c);
    return c;
  }

  function addRotatedCollider(x, z, w, d, h, ry) {
    const cw = Math.abs(Math.cos(ry)) * w + Math.abs(Math.sin(ry)) * d;
    const cd = Math.abs(Math.sin(ry)) * w + Math.abs(Math.cos(ry)) * d;
    return addCollider(x, z, cw, cd, h);
  }

  // ---------------------------------------------------------------- ground
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(120, 120, 1, 1), M.ground);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  // subtle ground elevation variation outside the compound (visual only)
  const outer = new THREE.Mesh(new THREE.PlaneGeometry(420, 420), new THREE.MeshStandardMaterial({ color: 0x5e5140, roughness: 1 }));
  outer.rotation.x = -Math.PI / 2;
  outer.position.y = -0.06;
  scene.add(outer);

  // -------------------------------------------------------------- sky dome
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: {
      uTop: { value: new THREE.Color(0x0a1a2b) },
      uMid: { value: new THREE.Color(0x3a4256) },
      uHorizon: { value: new THREE.Color(0xd58a52) },
      uSun: { value: new THREE.Color(0xffd9a0) },
      uSunDir: { value: new THREE.Vector3(-0.52, 0.3, -0.8).normalize() },
      uTime: { value: 0 },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      uniform vec3 uTop, uMid, uHorizon, uSun, uSunDir;
      uniform float uTime;
      varying vec3 vDir;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453123); }
      float noise(vec2 p){
        vec2 i = floor(p), f = fract(p);
        f = f*f*(3.0-2.0*f);
        return mix(mix(hash(i), hash(i+vec2(1,0)), f.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), f.x), f.y);
      }
      float fbm(vec2 p){
        float v = 0.0, a = 0.5;
        for (int i = 0; i < 5; i++){ v += a * noise(p); p *= 2.03; a *= 0.5; }
        return v;
      }
      void main() {
        vec3 d = normalize(vDir);
        float h = max(d.y, 0.0);
        vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.24, h));
        col = mix(col, uTop, smoothstep(0.18, 0.78, h));
        float sun = max(dot(d, uSunDir), 0.0);
        col += uSun * pow(sun, 900.0) * 3.0;
        col += uSun * pow(sun, 14.0) * 0.28;
        col += uSun * pow(sun, 3.0) * 0.05;
        vec2 uv = d.xz / max(d.y + 0.16, 0.06);
        float f = fbm(uv * 1.1 + vec2(uTime * 0.002, 0.0));
        f = smoothstep(0.54, 0.86, f);
        float band = smoothstep(-0.02, 0.18, d.y) * (1.0 - smoothstep(0.48, 0.72, d.y));
        col = mix(col, vec3(0.13, 0.125, 0.14), f * band * 0.5);
        float star = step(0.9985, hash(floor(d.xz * 700.0 + d.y * 200.0))) * smoothstep(0.3, 0.75, d.y);
        col += vec3(star) * 0.55;
        col = mix(col, uHorizon * 0.8, smoothstep(0.1, -0.06, d.y) * 0.6);
        gl_FragColor = vec4(col, 1.0);
      }`,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(430, 40, 24), skyMat);
  sky.renderOrder = -10;
  scene.add(sky);

  // ---------------------------------------------------------------- lights
  const hemi = new THREE.HemisphereLight(0x9ab9d8, 0x3b2f22, 0.65);
  scene.add(hemi);
  scene.add(new THREE.AmbientLight(0x2c3540, 0.45));

  const sun = new THREE.DirectionalLight(0xffb577, 2.6);
  sun.position.set(-42, 36, -30);
  sun.castShadow = true;
  const shadowSize = high ? 2048 : 1024;
  sun.shadow.mapSize.set(shadowSize, shadowSize);
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 150;
  sun.shadow.camera.left = -56;
  sun.shadow.camera.right = 56;
  sun.shadow.camera.top = 56;
  sun.shadow.camera.bottom = -56;
  sun.shadow.bias = -0.0007;
  sun.shadow.normalBias = 0.035;
  scene.add(sun);
  scene.add(sun.target);

  // warm bounce from the horizon
  const bounce = new THREE.DirectionalLight(0xff7d3d, 0.5);
  bounce.position.set(35, 8, -40);
  scene.add(bounce);

  // ------------------------------------------------------------ perimeter
  const wallH = 7.2;
  addBox(92, wallH, 1.6, M.concrete, 0, wallH / 2, -44);
  addBox(92, wallH, 1.6, M.concrete, 0, wallH / 2, 44);
  addBox(1.6, wallH, 92, M.concrete, -44, wallH / 2, 0);
  addBox(1.6, wallH, 92, M.concrete, 44, wallH / 2, 0);
  addCollider(0, -44, 92, 1.6, wallH);
  addCollider(0, 44, 92, 1.6, wallH);
  addCollider(-44, 0, 1.6, 92, wallH);
  addCollider(44, 0, 1.6, 92, wallH);

  // wall cap + buttresses
  for (const side of [-1, 1]) {
    addBox(92.4, 0.35, 2.0, M.concreteSmall, 0, wallH + 0.15, side * 44);
    addBox(2.0, 0.35, 92.4, M.concreteSmall, side * 44, wallH + 0.15, 0);
  }
  for (let i = -36; i <= 36; i += 12) {
    if (Math.abs(i) > 32) continue;
    addBox(0.9, wallH, 2.4, M.concreteSmall, i, wallH / 2, -43.2);
    addBox(0.9, wallH, 2.4, M.concreteSmall, i, wallH / 2, 43.2);
  }
  // razor wire
  if (med) {
    const wireMat = new THREE.MeshStandardMaterial({ color: 0x2a2d2e, roughness: 0.6, metalness: 0.8 });
    for (let side = -1; side <= 1; side += 2) {
      for (let i = -40; i <= 40; i += 1.6) {
        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.025, 4, 8), wireMat);
        ring.position.set(i, wallH + 0.55, side * 44);
        ring.rotation.y = Math.PI / 2;
        root.add(ring);
      }
    }
  }

  // ----------------------------------------------------------- back bunker
  const bunkerZ = -30;
  addBox(23, 7.5, 11, M.concrete, 0, 3.75, bunkerZ);
  addCollider(0, bunkerZ, 23, 11, 7.5);
  addBox(24, 0.4, 12, M.concreteSmall, 0, 7.65, bunkerZ);
  // entrance recess
  addBox(4.2, 4.6, 0.35, M.darkMetal, 0, 2.3, bunkerZ + 5.6);
  addBox(3.2, 3.8, 0.2, M.gunmetal, 0, 1.9, bunkerZ + 5.78);
  addBox(0.16, 3.2, 0.12, M.cyanLamp, 1.35, 1.9, bunkerZ + 5.9);
  addBox(0.16, 3.2, 0.12, M.cyanLamp, -1.35, 1.9, bunkerZ + 5.9);
  // slit windows
  for (const x of [-8.2, -5.5, 5.5, 8.2]) {
    addBox(2.2, 0.55, 0.22, M.glass, x, 4.4, bunkerZ + 5.55);
    addBox(2.5, 0.22, 0.34, M.darkMetal, x, 4.75, bunkerZ + 5.6);
  }
  // roof antenna + dishes
  const mast = addBox(0.14, 7, 0.14, M.darkMetal, -7, 11.2, bunkerZ - 2);
