// Fully procedural WebAudio sound design — no external assets.
import { clamp, rand } from './utils.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.volume = 0.7;
    this.noise = null;
    this.ambientStarted = false;
    this.lastHeartbeat = 0;
    this.lastAmbient = 0;
    this.enabled = true;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) { this.enabled = false; return; }
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.volume;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.24;
    this.master.connect(comp);
    comp.connect(ctx.destination);

    this.sfxGain = ctx.createGain();
    this.sfxGain.gain.value = 0.9;
    this.sfxGain.connect(this.master);

    // small procedural reverb
    const convolver = ctx.createConvolver();
    const len = Math.floor(ctx.sampleRate * 1.8);
    const impulse = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let c = 0; c < 2; c++) {
      const d = impulse.getChannelData(c);
      for (let i = 0; i < len; i++) {
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 3.4);
      }
    }
    convolver.buffer = impulse;
    this.reverb = ctx.createGain();
    this.reverb.gain.value = 0.24;
    this.reverb.connect(convolver);
    convolver.connect(this.master);

    // shared noise buffer
    const nlen = Math.floor(ctx.sampleRate * 2);
    const nb = ctx.createBuffer(1, nlen, ctx.sampleRate);
    const nd = nb.getChannelData(0);
    for (let i = 0; i < nlen; i++) nd[i] = Math.random() * 2 - 1;
    this.noise = nb;

    this.startAmbient();
  }

  resume() {
    if (!this.ctx) this.init();
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setVolume(v) {
    this.volume = clamp(v, 0, 1);
    if (this.master) this.master.gain.setTargetAtTime(this.volume, this.ctx.currentTime, 0.05);
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  noiseSource(duration) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    src.playbackRate.value = rand(0.85, 1.15);
    return src;
  }

  env(node, t0, peak, attack, decay, hold = 0) {
    const g = node.gain;
    g.cancelScheduledValues(t0);
    g.setValueAtTime(0.0001, t0);
    g.exponentialRampToValueAtTime(Math.max(0.0002, peak), t0 + attack);
    if (hold > 0) g.setValueAtTime(Math.max(0.0002, peak), t0 + attack + hold);
    g.exponentialRampToValueAtTime(0.0001, t0 + attack + hold + decay);
  }

  panner(pan = 0) {
    if (!this.ctx.createStereoPanner) return null;
    const p = this.ctx.createStereoPanner();
    p.pan.value = clamp(pan, -1, 1);
    return p;
  }

  route(node, pan = 0, reverbAmount = 0.2) {
    const p = this.panner(pan);
    if (p) { node.connect(p); p.connect(this.sfxGain); if (reverbAmount > 0) p.connect(this.reverb); }
    else { node.connect(this.sfxGain); }
    return p;
  }

  // ---------------------------------------------------------------- weapons
  shot(kind = 'rifle', pan = 0) {
    if (!this.ctx || !this.enabled) return;
    const t = this.now();
    const out = this.ctx.createGain();
    this.route(out, pan, 0.35);
    const heavy = kind === 'heavy';
    const pistol = kind === 'pistol';
    const peak = heavy ? 0.85 : pistol ? 0.55 : 0.72;

    // body noise
    const n = this.noiseSource(0.25);
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(heavy ? 2600 : 5200, t);
    lp.frequency.exponentialRampToValueAtTime(heavy ? 220 : 700, t + 0.22);
    lp.Q.value = 0.9;
    n.connect(lp); lp.connect(out);
    this.env(out, t, peak, 0.003, heavy ? 0.42 : 0.22);
    n.start(t); n.stop(t + 0.5);

    // punch oscillator
    const o = this.ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(heavy ? 90 : pistol ? 160 : 120, t);
    o.frequency.exponentialRampToValueAtTime(34, t + 0.18);
    const og = this.ctx.createGain();
    og.gain.setValueAtTime(0.0001, t);
    og.gain.exponentialRampToValueAtTime(peak * 0.9, t + 0.004);
    og.gain.exponentialRampToValueAtTime(0.0001, t + (heavy ? 0.4 : 0.2));
    o.connect(og); og.connect(out);
    o.start(t); o.stop(t + 0.45);

    // mechanical crack
    const crack = this.ctx.createOscillator();
    crack.type = 'square';
    crack.frequency.setValueAtTime(rand(2200, 3400), t);
    crack.frequency.exponentialRampToValueAtTime(700, t + 0.03);
    const cg = this.ctx.createGain();
    cg.gain.setValueAtTime(0.0001, t);
    cg.gain.exponentialRampToValueAtTime(0.16, t + 0.002);
    cg.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
    crack.connect(cg); cg.connect(out);
    crack.start(t); crack.stop(t + 0.07);

    // distant echo
    const e = this.noiseSource(0.4);
    const ef = this.ctx.createBiquadFilter();
    ef.type = 'bandpass'; ef.frequency.value = 420; ef.Q.value = 1.2;
    const eg = this.ctx.createGain();
    eg.gain.setValueAtTime(0.0001, t + 0.09);
    eg.gain.exponentialRampToValueAtTime(0.12, t + 0.12);
    eg.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);
    e.connect(ef); ef.connect(eg); eg.connect(this.reverb);
    e.start(t + 0.09); e.stop(t + 0.6);
  }

  dryFire() {
    if (!this.ctx) return;
    const t = this.now();
    const n = this.noiseSource(0.04);
    const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 2200;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.045);
    n.connect(f); f.connect(g); g.connect(this.sfxGain);
    n.start(t); n.stop(t + 0.05);
  }

  reload(stage = 0) {
    if (!this.ctx) return;
    const t = this.now() + stage * 0.42;
    const click = (freq, dur, vol) => {
      const o = this.ctx.createOscillator();
      o.type = 'square';
      o.frequency.value = freq;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + 0.003);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); g.connect(this.sfxGain);
      o.start(t); o.stop(t + dur + 0.02);
      const n = this.noiseSource(0.03);
      const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq * 1.5;
      const ng = this.ctx.createGain(); ng.gain.setValueAtTime(vol * 0.7, t); ng.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      n.connect(f); f.connect(ng); ng.connect(this.sfxGain);
      n.start(t); n.stop(t + dur + 0.02);
    };
    click(1800, 0.05, 0.16);
    click(1200, 0.08, 0.12);
    if (stage >= 1) click(900, 0.1, 0.18);
  }

  swap() { this.reload(0); }

  // --------------------------------------------------------------- feedback
  hit(headshot = false) {
    if (!this.ctx) return;
    const t = this.now();
    const o = this.ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(headshot ? 1500 : 1050, t);
    o.frequency.exponentialRampToValueAtTime(headshot ? 2100 : 1400, t + 0.05);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(headshot ? 0.24 : 0.17, t + 0.003);
    g.gain.exponentialRampToValueAtTime(0.0001, t + (headshot ? 0.22 : 0.11));
    o.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.25);
    if (headshot) {
      const o2 = this.ctx.createOscillator();
      o2.type = 'triangle'; o2.frequency.value = 2600;
      const g2 = this.ctx.createGain();
      g2.gain.setValueAtTime(0.0001, t + 0.03);
      g2.gain.exponentialRampToValueAtTime(0.12, t + 0.035);
      g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
      o2.connect(g2); g2.connect(this.sfxGain);
      o2.start(t + 0.03); o2.stop(t + 0.2);
    }
  }

  kill() {
    if (!this.ctx) return;
    const t = this.now();
    const o = this.ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(420, t);
    o.frequency.exponentialRampToValueAtTime(90, t + 0.22);
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 900;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.18, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
    o.connect(f); f.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.3);
  }

  hurt(pan = 0) {
    if (!this.ctx) return;
    const t = this.now();
    const n = this.noiseSource(0.2);
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 500;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.45, t + 0.005); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    const p = this.panner(pan);
    n.connect(f); f.connect(g); if (p) { g.connect(p); p.connect(this.sfxGain); } else g.connect(this.sfxGain);
    n.start(t); n.stop(t + 0.35);
    const o = this.ctx.createOscillator();
    o.type = 'sine'; o.frequency.setValueAtTime(70, t); o.frequency.exponentialRampToValueAtTime(38, t + 0.25);
    const og = this.ctx.createGain(); og.gain.setValueAtTime(0.0001, t); og.gain.exponentialRampToValueAtTime(0.5, t + 0.005); og.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    o.connect(og); og.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.32);
  }

  explosion(pan = 0, distance = 1) {
    if (!this.ctx) return;
    const t = this.now();
    const vol = clamp(1.1 / (1 + distance * 0.06), 0.1, 0.9);
    const n = this.noiseSource(1.6);
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass';
    f.frequency.setValueAtTime(3000, t); f.frequency.exponentialRampToValueAtTime(90, t + 1.1);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + 1.4);
    const p = this.panner(pan);
    n.connect(f); f.connect(g); if (p) { g.connect(p); p.connect(this.sfxGain); p.connect(this.reverb); } else { g.connect(this.sfxGain); g.connect(this.reverb); }
    n.start(t); n.stop(t + 1.6);
    const o = this.ctx.createOscillator();
    o.type = 'sine'; o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(28, t + 0.8);
    const og = this.ctx.createGain(); og.gain.setValueAtTime(0.0001, t); og.gain.exponentialRampToValueAtTime(vol * 0.9, t + 0.01); og.gain.exponentialRampToValueAtTime(0.0001, t + 1.1);
    o.connect(og); og.connect(this.sfxGain);
    o.start(t); o.stop(t + 1.2);
  }

  pickup() {
    if (!this.ctx) return;
    const t = this.now();
    [660, 880, 1320].forEach((freq, i) => {
      const o = this.ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
      const g = this.ctx.createGain();
      const tt = t + i * 0.07;
      g.gain.setValueAtTime(0.0001, tt); g.gain.exponentialRampToValueAtTime(0.14, tt + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, tt + 0.18);
      o.connect(g); g.connect(this.sfxGain);
      o.start(tt); o.stop(tt + 0.2);
    });
  }

  waveStart() {
    if (!this.ctx) return;
    const t = this.now();
    const o = this.ctx.createOscillator(); o.type = 'sawtooth';
    o.frequency.setValueAtTime(110, t); o.frequency.linearRampToValueAtTime(165, t + 0.5);
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 600;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.14, t + 0.08); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    o.connect(f); f.connect(g); g.connect(this.sfxGain); g.connect(this.reverb);
    o.start(t); o.stop(t + 1);
    for (let i = 0; i < 2; i++) {
      const tt = t + 0.15 + i * 0.24;
      const b = this.ctx.createOscillator(); b.type = 'square'; b.frequency.value = i ? 880 : 660;
      const bg = this.ctx.createGain(); bg.gain.setValueAtTime(0.0001, tt); bg.gain.exponentialRampToValueAtTime(0.06, tt + 0.005); bg.gain.exponentialRampToValueAtTime(0.0001, tt + 0.12);
      b.connect(bg); bg.connect(this.sfxGain);
      b.start(tt); b.stop(tt + 0.14);
    }
  }

  victory() {
    if (!this.ctx) return;
    const t = this.now();
    [392, 523, 659, 784].forEach((freq, i) => {
      const o = this.ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
      const g = this.ctx.createGain();
      const tt = t + i * 0.16;
      g.gain.setValueAtTime(0.0001, tt); g.gain.exponentialRampToValueAtTime(0.16, tt + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, tt + 0.6);
      o.connect(g); g.connect(this.sfxGain); g.connect(this.reverb);
      o.start(tt); o.stop(tt + 0.65);
    });
  }

  defeat() {
    if (!this.ctx) return;
    const t = this.now();
    [220, 174, 130].forEach((freq, i) => {
      const o = this.ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = freq;
      const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 500;
      const g = this.ctx.createGain();
      const tt = t + i * 0.28;
      g.gain.setValueAtTime(0.0001, tt); g.gain.exponentialRampToValueAtTime(0.14, tt + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, tt + 0.9);
      o.connect(f); f.connect(g); g.connect(this.sfxGain); g.connect(this.reverb);
      o.start(tt); o.stop(tt + 1);
    });
  }

  ui(click = false) {
    if (!this.ctx) return;
    const t = this.now();
    const o = this.ctx.createOscillator(); o.type = 'sine'; o.frequency.value = click ? 520 : 880;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.05, t + 0.004); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
    o.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + 0.1);
  }

  heartbeat() {
    if (!this.ctx) return;
    const t = this.now();
    for (let i = 0; i < 2; i++) {
      const tt = t + i * 0.16;
      const o = this.ctx.createOscillator(); o.type = 'sine';
      o.frequency.setValueAtTime(58, tt); o.frequency.exponentialRampToValueAtTime(40, tt + 0.12);
      const g = this.ctx.createGain(); g.gain.setValueAtTime(0.0001, tt); g.gain.exponentialRampToValueAtTime(i ? 0.08 : 0.14, tt + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, tt + 0.18);
      o.connect(g); g.connect(this.sfxGain);
      o.start(tt); o.stop(tt + 0.2);
    }
  }

  // --------------------------------------------------------------- ambient
  startAmbient() {
    if (!this.ctx || this.ambientStarted) return;
    this.ambientStarted = true;
    const ctx = this.ctx;
    const wind = ctx.createBufferSource();
    wind.buffer = this.noise; wind.loop = true;
    const wf = ctx.createBiquadFilter(); wf.type = 'lowpass'; wf.frequency.value = 420; wf.Q.value = 0.5;
    const wg = ctx.createGain(); wg.gain.value = 0.045;
    wind.connect(wf); wf.connect(wg); wg.connect(this.master);
    wind.start();

    const hum = ctx.createOscillator(); hum.type = 'sine'; hum.frequency.value = 54;
    const hg = ctx.createGain(); hg.gain.value = 0.012;
    hum.connect(hg); hg.connect(this.master); hum.start();

    const hum2 = ctx.createOscillator(); hum2.type = 'triangle'; hum2.frequency.value = 108.5;
    const hg2 = ctx.createGain(); hg2.gain.value = 0.004;
    hum2.connect(hg2); hg2.connect(this.master); hum2.start();
  }

  update(dt, { health = 100, playing = false } = {}) {
    if (!this.ctx) return;
    const now = this.now();
    if (playing && health < 34 && now - this.lastHeartbeat > (health < 20 ? 0.62 : 0.9)) {
      this.lastHeartbeat = now;
      this.heartbeat();
    }
    if (playing && now - this.lastAmbient > 18 && Math.random() < 0.3) {
      this.lastAmbient = now;
      const pan = rand(-0.8, 0.8);
      const t = now;
      const n = this.noiseSource(1.4);
      const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 180;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.07, t + 0.4); g.gain.exponentialRampToValueAtTime(0.0001, t + 2.2);
      const p = this.panner(pan);
      n.connect(f); f.connect(g); if (p) { g.connect(p); p.connect(this.reverb); } else g.connect(this.reverb);
      n.start(t); n.stop(t + 2.3);
    }
  }
}

import * as THREE from 'three';
import { rand, pick, clamp } from './utils.js';

const PARTICLE_VERT = `
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vAlpha = aAlpha;
    vColor = aColor;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (420.0 / max(0.1, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;
const PARTICLE_FRAG = `
  uniform sampler2D uMap;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vec4 t = texture2D(uMap, gl_PointCoord);
    if (t.a * vAlpha < 0.004) discard;
    gl_FragColor = vec4(vColor, t.a * vAlpha);
  }
`;

class ParticlePool {
  constructor(scene, map, capacity, additive) {
    this.capacity = capacity;
    this.items = new Array(capacity).fill(null).map(() => ({ life: 0, max: 1, vel: new THREE.Vector3(), gravity: 0, drag: 1, grow: 0 }));
    this.pos = new Float32Array(capacity * 3);
    this.col = new Float32Array(capacity * 3);
    this.size = new Float32Array(capacity);
    this.alpha = new Float32Array(capacity);
    this.cursor = 0;
    for (let i = 0; i < capacity; i++) this.pos[i * 3 + 1] = -999;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    const mat = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: map } },
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 3;
    scene.add(this.points);
  }

  spawn(p) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.capacity;
    const it = this.items[i];
    it.life = p.life;
    it.max = p.life;
    it.vel.copy(p.vel);
    it.gravity = p.gravity ?? 0;
    it.drag = p.drag ?? 1;
    it.grow = p.grow ?? 0;
    it.baseSize = p.size;
    this.pos[i * 3] = p.pos.x;
    this.pos[i * 3 + 1] = p.pos.y;
    this.pos[i * 3 + 2] = p.pos.z;
    this.col[i * 3] = p.color.r;
    this.col[i * 3 + 1] = p.color.g;
    this.col[i * 3 + 2] = p.color.b;
    this.size[i] = p.size;
    this.alpha[i] = p.alpha ?? 1;
  }

  update(dt) {
    for (let i = 0; i < this.capacity; i++) {
      const it = this.items[i];
      if (it.life <= 0) continue;
      it.life -= dt;
      if (it.life <= 0) {
        this.alpha[i] = 0;
        this.pos[i * 3 + 1] = -999;
        continue;
      }
      it.vel.y += it.gravity * dt;
      const drag = Math.pow(it.drag, dt * 60);
      it.vel.multiplyScalar(drag);
      this.pos[i * 3] += it.vel.x * dt;
      this.pos[i * 3 + 1] += it.vel.y * dt;
      this.pos[i * 3 + 2] += it.vel.z * dt;
      if (this.pos[i * 3 + 1] < 0.02 && it.gravity < 0) {
        this.pos[i * 3 + 1] = 0.02;
        it.vel.y *= -0.28;
        it.vel.x *= 0.5;
        it.vel.z *= 0.5;
      }
      const t = it.life / it.max;
      this.alpha[i] = t * t;
      if (it.grow) this.size[i] = it.baseSize * (1 + (1 - t) * it.grow);
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.aAlpha.needsUpdate = true;
    this.points.geometry.attributes.aSize.needsUpdate = true;
    this.points.geometry.attributes.aColor.needsUpdate = true;
  }

  clear() {
    for (let i = 0; i < this.capacity; i++) {
      this.items[i].life = 0;
      this.alpha[i] = 0;
      this.pos[i * 3 + 1] = -999;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

export class Effects {
  constructor(scene, camera, T) {
    this.scene = scene;
    this.camera = camera;
    this.T = T;
    this.sparks = new ParticlePool(scene, T.glow, 700, true);
    this.smoke = new ParticlePool(scene, T.smoke, 260, false);
    this.decals = [];
    this.decalCursor = 0;
    this.decalMat = new THREE.MeshBasicMaterial({ map: T.bulletHole, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, toneMapped: false });
    for (let i = 0; i < 100; i++) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), this.decalMat);
      m.visible = false;
      m.renderOrder = 2;
      scene.add(m);
      this.decals.push(m);
    }
    this.tracers = [];
    for (let i = 0; i < 36; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: 0xffd9a0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
      const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 1, 5, 1, true), mat);
      mesh.visible = false;
      mesh.frustumCulled = false;
      scene.add(mesh);
      this.tracers.push({ mesh, life: 0, max: 0.08 });
    }
    this.tracerCursor = 0;
    this.flashes = [];
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.SpriteMaterial({ map: T.flash, color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
      const s = new THREE.Sprite(mat);
      s.visible = false;
      scene.add(s);
      this.flashes.push({ sprite: s, life: 0, max: 0.08, base: 1 });
    }
    this.flashCursor = 0;
    this.shockwaves = [];
    for (let i = 0; i < 6; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: 0xffa050, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
      const mesh = new THREE.Mesh(new THREE.RingGeometry(0.6, 0.78, 40), mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.visible = false;
      scene.add(mesh);
      this.shockwaves.push({ mesh, life: 0, max: 0.55 });
    }
    this.shockCursor = 0;
    this.shells = [];
    for (let i = 0; i < 20; i++) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(0.018, 0.018, 0.045), new THREE.MeshStandardMaterial({ color: 0xc9a15a, roughness: 0.35, metalness: 0.9 }));
      mesh.visible = false;
      mesh.castShadow = false;
      scene.add(mesh);
      this.shells.push({ mesh, vel: new THREE.Vector3(), life: 0, spin: new THREE.Vector3() });
    }
    this.shellCursor = 0;
    this.lights = [];
    for (let i = 0; i < 3; i++) {
      const l = new THREE.PointLight(0xff9040, 0, 18, 1.8);
      scene.add(l);
      this.lights.push({ light: l, life: 0, max: 0.25, peak: 0 });
    }
    this.lightCursor = 0;
    this._v = new THREE.Vector3();
    this._q = new THREE.Quaternion();
    this._up = new THREE.Vector3(0, 1, 0);
  }

  spawnSparks(pos, normal, count = 10, color = new THREE.Color(0xffb060), speed = 4, size = 0.09, life = 0.5) {
    for (let i = 0; i < count; i++) {
      const dir = new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1)).normalize();
      if (normal) dir.multiplyScalar(0.5).add(normal).normalize();
      const v = dir.multiplyScalar(speed * rand(0.25, 1.1));
      const c = color.clone().offsetHSL(rand(-0.02, 0.02), 0, rand(-0.08, 0.08));
      this.sparks.spawn({
        pos: this._v.copy(pos).add(new THREE.Vector3(rand(-0.05, 0.05), rand(-0.05, 0.05), rand(-0.05, 0.05))),
        vel: v,
        color: c,
        size: size * rand(0.5, 1.5),
        life: life * rand(0.5, 1.3),
        gravity: -11,
        drag: 0.965,
      });
    }
  }

  spawnDust(pos, normal, count = 5) {
    for (let i = 0; i < count; i++) {
      const v = new THREE.Vector3(rand(-1, 1), rand(0.1, 1), rand(-1, 1)).normalize().multiplyScalar(rand(0.4, 1.6));
      if (normal) v.add(normal.clone().multiplyScalar(0.8));
      this.smoke.spawn({
        pos: this._v.copy(pos).add(new THREE.Vector3(rand(-0.1, 0.1), rand(-0.1, 0.1), rand(-0.1, 0.1))),
        vel: v,
        color: new THREE.Color(0x8a8175),
        size: rand(0.4, 0.9),
        life: rand(0.7, 1.5),
        gravity: 0.4,
        drag: 0.94,
        alpha: 0.35,
        grow: 2.4,
      });
    }
  }

  spawnBlood(pos, dir, count = 12) {
    for (let i = 0; i < count; i++) {
      const v = new THREE.Vector3(rand(-1, 1), rand(-0.4, 1.4), rand(-1, 1)).normalize().multiplyScalar(rand(1, 4));
      if (dir) v.add(dir.clone().multiplyScalar(rand(0.5, 2)));
      this.sparks.spawn({
        pos: this._v.copy(pos),
        vel: v,
        color: new THREE.Color(pick([0xff3018, 0xb00d08, 0xff6a40])),
        size: rand(0.04, 0.11),
        life: rand(0.25, 0.7),
        gravity: -14,
        drag: 0.96,
      });
    }
  }

  tracer(from, to, color = 0xffd9a0) {
    const t = this.tracers[this.tracerCursor];
    this.tracerCursor = (this.tracerCursor + 1) % this.tracers.length;
    const dir = this._v.copy(to).sub(from);
    const len = dir.length();
    if (len < 0.01) return;
    dir.normalize();
    t.mesh.position.copy(from).addScaledVector(dir, len / 2);
    t.mesh.quaternion.setFromUnitVectors(this._up, dir);
    t.mesh.scale.set(1, len, 1);
    t.mesh.material.color.setHex(color);
    t.mesh.material.opacity = 0.9;
    t.mesh.visible = true;
    t.life = 0.075;
    t.max = 0.075;
  }

  muzzleFlash(pos, scale = 1, color = 0xffb050) {
    const f = this.flashes[this.flashCursor];
    this.flashCursor = (this.flashCursor + 1) % this.flashes.length;
    f.sprite.position.copy(pos);
    f.sprite.material.color.setHex(color);
    f.sprite.material.rotation = rand(0, Math.PI * 2);
    f.sprite.scale.setScalar(scale * rand(0.7, 1.15));
    f.sprite.material.opacity = 1;
    f.sprite.visible = true;
    f.life = 0.06;
    f.max = 0.06;
    f.base = scale;
    const l = this.lights[this.lightCursor];
    this.lightCursor = (this.lightCursor + 1) % this.lights.length;
    l.light.position.copy(pos);
    l.light.color.setHex(color);
    l.light.intensity = 40 * scale;
    l.life = 0.08;
    l.max = 0.08;
    l.peak = 40 * scale;
  }

  decal(point, normal, scale = 1) {
    const m = this.decals[this.decalCursor];
    this.decalCursor = (this.decalCursor + 1) % this.decals.length;
    m.position.copy(point).addScaledVector(normal, 0.012);
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal);
    m.rotateZ(rand(0, Math.PI * 2));
    const s = rand(0.12, 0.2) * scale;
    m.scale.set(s, s, s);
    m.visible = true;
    m.userData.life = 26;
  }

  impact(point, normal, kind = 'wall') {
    if (kind === 'enemy') {
      this.spawnBlood(point, normal, 10);
      this.spawnSparks(point, normal, 4, new THREE.Color(0xff7040), 2.5, 0.06, 0.3);
    } else {
      this.spawnSparks(point, normal, 8, new THREE.Color(0xffc070), 3.4, 0.07, 0.45);
      this.spawnDust(point, normal, 3);
      if (normal.y < 0.7) this.decal(point, normal);
    }
  }

  explosion(pos, radius = 5) {
    // fireball
    const f = this.flashes[this.flashCursor];
    this.flashCursor = (this.flashCursor + 1) % this.flashes.length;
    f.sprite.position.copy(pos);
    f.sprite.material.color.setHex(0xffa040);
    f.sprite.scale.setScalar(radius * 1.3);
    f.sprite.material.opacity = 1;
    f.sprite.visible = true;
    f.life = 0.24;
    f.max = 0.24;
    f.base = radius * 1.3;
    const l = this.lights[this.lightCursor];
    this.lightCursor = (this.lightCursor + 1) % this.lights.length;
    l.light.position.copy(pos).add(new THREE.Vector3(0, 1, 0));
    l.light.color.setHex(0xff8030);
    l.light.intensity = 900;
    l.life = 0.4;
    l.max = 0.4;
    l.peak = 900;
    this.spawnSparks(pos, null, 46, new THREE.Color(0xffa040), 13, 0.16, 0.9);
    this.spawnSparks(pos, null, 20, new THREE.Color(0xfff0c0), 18, 0.08, 0.5);
    for (let i = 0; i < 14; i++) {
      const v = new THREE.Vector3(rand(-1, 1), rand(0.2, 1.4), rand(-1, 1)).normalize().multiplyScalar(rand(1, 5));
      this.smoke.spawn({
        pos: this._v.copy(pos).add(new THREE.Vector3(rand(-0.5, 0.5), rand(0, 1), rand(-0.5, 0.5))),
        vel: v,
        color: new THREE.Color(pick([0x2b2824, 0x3d3831, 0x1e1c19])),
        size: rand(1.5, 3.5),
        life: rand(1.6, 3.2),
        gravity: 0.7,
        drag: 0.93,
        alpha: 0.55,
        grow: 2.6,
      });
    }
    const s = this.shockwaves[this.shockCursor];
    this.shockCursor = (this.shockCursor + 1) % this.shockwaves.length;
    s.mesh.position.copy(pos);
    s.mesh.position.y = 0.06;
    s.mesh.scale.setScalar(1);
    s.mesh.material.opacity = 0.8;
    s.mesh.visible = true;
    s.life = 0.5;
    s.max = 0.5;
  }

  shell(pos, dir) {
    const s = this.shells[this.shellCursor];
    this.shellCursor = (this.shellCursor + 1) % this.shells.length;
    s.mesh.position.copy(pos);
    s.vel.copy(dir).multiplyScalar(rand(1.8, 3.2));
    s.vel.y += rand(1.2, 2.4);
    s.spin.set(rand(-18, 18), rand(-18, 18), rand(-18, 18));
    s.mesh.visible = true;
    s.life = 1.6;
  }

  update(dt) {
    this.sparks.update(dt);
    this.smoke.update(dt);
    for (const t of this.tracers) {
      if (t.life <= 0) continue;
      t.life -= dt;
      t.mesh.material.opacity = Math.max(0, t.life / t.max) * 0.9;
      if (t.life <= 0) t.mesh.visible = false;
    }
    for (const f of this.flashes) {
      if (f.life <= 0) continue;
      f.life -= dt;
      const k = Math.max(0, f.life / f.max);
      f.sprite.material.opacity = k;
      f.sprite.scale.setScalar(f.base * (1 + (1 - k) * 0.8));
      if (f.life <= 0) f.sprite.visible = false;
    }
    for (const l of this.lights) {
      if (l.life <= 0) continue;
      l.life -= dt;
      l.light.intensity = Math.max(0, l.life / l.max) * l.peak;
    }
    for (const s of this.shockwaves) {
      if (s.life <= 0) continue;
      s.life -= dt;
      const k = 1 - s.life / s.max;
      s.mesh.scale.setScalar(1 + k * 7);
      s.mesh.material.opacity = Math.max(0, 1 - k) * 0.8;
      if (s.life <= 0) s.mesh.visible = false;
    }
    for (const s of this.shells) {
      if (s.life <= 0) continue;
      s.life -= dt;
      s.vel.y -= 14 * dt;
      s.mesh.position.addScaledVector(s.vel, dt);
      s.mesh.rotation.x += s.spin.x * dt;
      s.mesh.rotation.y += s.spin.y * dt;
      s.mesh.rotation.z += s.spin.z * dt;
      if (s.mesh.position.y < 0.03) {
        s.mesh.position.y = 0.03;
        s.vel.y *= -0.35;
        s.vel.x *= 0.7; s.vel.z *= 0.7;
      }
      if (s.life <= 0) s.mesh.visible = false;
    }
    for (const m of this.decals) {
      if (!m.visible) continue;
      m.userData.life -= dt;
      if (m.userData.life <= 0) m.visible = false;
    }
  }

  clear() {
    this.sparks.clear();
    this.smoke.clear();
    for (const t of this.tracers) { t.life = 0; t.mesh.visible = false; }
    for (const f of this.flashes) { f.life = 0; f.sprite.visible = false; }
    for (const s of this.shockwaves) { s.life = 0; s.mesh.visible = false; }
    for (const s of this.shells) { s.life = 0; s.mesh.visible = false; }
    for (const m of this.decals) m.visible = false;
    for (const l of this.lights) { l.life = 0; l.light.intensity = 0; }
  }
}

