    this.rings.push({ mesh: ring, life: 0.9, max: 0.9 });
    this.effects.spawnSparks(new THREE.Vector3(pos.x, 0.3, pos.z), new THREE.Vector3(0, 1, 0), 14, new THREE.Color(0xff4a20), 2.4, 0.1, 0.7);
    return e;
