  buildModel(type, e) {
    const g = new THREE.Group();
    const armor = new THREE.MeshStandardMaterial({ color: type.color, roughness: 0.48, metalness: 0.68 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x15191c, roughness: 0.4, metalness: 0.85 });
    const trim = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, emissive: type.trim, emissiveIntensity: 2.4, roughness: 0.35, metalness: 0.4 });
    const visor = new THREE.MeshStandardMaterial({ color: 0x050505, emissive: type.trim, emissiveIntensity: 4.2, roughness: 0.2, metalness: 0.6 });
    e.materials = [armor, dark, trim, visor];
    e.armorMat = armor;
    e.visorMat = visor;

    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.62, 0.36), armor);
    torso.position.y = 1.24;
    torso.castShadow = true; torso.receiveShadow = true;
    g.add(torso);
    const chest = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.36, 0.16), dark);
    chest.position.set(0, 1.28, 0.22);
    chest.castShadow = true;
    g.add(chest);
    const core = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 0.05), trim);
    core.position.set(0, 1.3, 0.31);
    g.add(core);
    // pelvis
    const pelvis = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.24, 0.32), dark);
    pelvis.position.y = 0.86;
    pelvis.castShadow = true;
    g.add(pelvis);
    // shoulders
    for (const s of [-1, 1]) {
      const pad = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.2, 0.34), armor);
      pad.position.set(s * 0.4, 1.48, 0);
      pad.rotation.z = s * 0.16;
      pad.castShadow = true;
      g.add(pad);
    }
    // head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.28, 0.3), armor);
    head.position.y = 1.7;
    head.castShadow = true;
    g.add(head);
    const helmet = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.1, 0.34), dark);
    helmet.position.y = 1.84;
    g.add(helmet);
    const visorBar = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.07, 0.03), visor);
    visorBar.position.set(0, 1.72, 0.16);
    g.add(visorBar);
    // antenna
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.34, 4), dark);
    ant.position.set(0.12, 1.98, -0.06);
    ant.rotation.z = -0.18;
    g.add(ant);
    // visor glow
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.T.glow, color: type.trim, transparent: true, opacity: 0.85, depthWrite: false, blending: THREE.AdditiveBlending }));
    glow.scale.set(0.55, 0.55, 1);
    glow.position.set(0, 1.72, 0.2);
    g.add(glow);
    e.visorGlow = glow;

    // limbs
    const limbs = {};
    for (const s of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(s * 0.4, 1.44, 0);
      g.add(shoulder);
      const upper = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.42, 0.16), armor);
      upper.position.y = -0.2;
      upper.castShadow = true;
      shoulder.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.42;
      shoulder.add(elbow);
      const lower = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.38, 0.14), dark);
      lower.position.y = -0.18;
      lower.castShadow = true;
      elbow.add(lower);
      const hand = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.14), armor);
      hand.position.y = -0.4;
      elbow.add(hand);
      limbs[s < 0 ? 'leftArm' : 'rightArm'] = shoulder;
      limbs[s < 0 ? 'leftElbow' : 'rightElbow'] = elbow;

      const hip = new THREE.Group();
      hip.position.set(s * 0.16, 0.84, 0);
      g.add(hip);
      const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.46, 0.21), armor);
      thigh.position.y = -0.22;
      thigh.castShadow = true;
      hip.add(thigh);
      const knee = new THREE.Group();
      knee.position.y = -0.45;
      hip.add(knee);
      const shin = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.38, 0.18), dark);
      shin.position.y = -0.18;
      shin.castShadow = true;
      knee.add(shin);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.12, 0.3), armor);
      boot.position.set(0, -0.38, 0.05);
      knee.add(boot);
      limbs[s < 0 ? 'leftLeg' : 'rightLeg'] = hip;
      limbs[s < 0 ? 'leftKnee' : 'rightKnee'] = knee;
    }
    e.limbs = limbs;

    // weapon
    const muzzle = new THREE.Object3D();
    if (type.melee) {
      for (const s of [-1, 1]) {
        const blade = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.62), trim);
        blade.position.set(s * 0.24, 1.1, 0.42);
        blade.rotation.x = 0.18;
        g.add(blade);
      }
      muzzle.position.set(0, 1.2, 0.72);
      g.add(muzzle);
    } else {
      const gun = new THREE.Group();
      gun.position.set(0.32, 1.3, 0.34);
      g.add(gun);
      const body = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.14, 0.62), dark);
      body.position.z = 0.18;
      body.castShadow = true;
      gun.add(body);
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.034, 0.5, 6), armor);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.z = 0.65;
      gun.add(barrel);
      const mag = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.2, 0.12), armor);
      mag.position.set(0, -0.14, 0.12);
      mag.rotation.x = 0.2;
      gun.add(mag);
      if (type.burst) {
        const drum = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.16, 10), dark);
        drum.rotation.z = Math.PI / 2;
        drum.position.set(0, -0.13, 0.3);
        gun.add(drum);
      }
      const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.08, 6), trim);
      tip.rotation.x = Math.PI / 2;
      tip.position.z = 0.91;
      gun.add(tip);
      muzzle.position.set(0.32, 1.3, 0.95);
      g.add(muzzle);
    }
    e.muzzle = muzzle;

    if (type.boss) {
      // heavy shoulder pods and crown
      for (const s of [-1, 1]) {
        const pod = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.34, 0.44), dark);
        pod.position.set(s * 0.5, 1.56, -0.1);
        pod.castShadow = true;
        g.add(pod);
        const light = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.05), trim);
        light.position.set(s * 0.5, 1.56, 0.13);
        g.add(light);
      }
      const crown = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.08, 0.1), trim);
      crown.position.set(0, 1.94, 0);
      g.add(crown);
    } else if (typeName === 'heavy') {
      const shield = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.5, 0.1), armor);
      shield.position.set(0, 1.25, 0.31);
      shield.castShadow = true;
      g.add(shield);
    }
    return g;
  }

  hasLOS(from, to, colliders) {
    const dir = _v1.copy(to).sub(from);
    const dist = dir.length();
    if (dist < 0.001) return true;
    dir.multiplyScalar(1 / dist);
    for (const c of colliders) {
      const t = rayAABB(from, dir, c);
      if (t < dist - 0.15) return false;
    }
    return true;
  }

  update(dt, time, player, world) {
    this.time = time;
    const colliders = world.colliders;
    const playerPos = player.position;
    const playerChest = _v2.set(playerPos.x, playerPos.y + player.eyeHeight * 0.72, playerPos.z);

    for (const ring of this.rings) {
      ring.life -= dt;
      const k = 1 - ring.life / ring.max;
      ring.mesh.scale.setScalar(1 + k * 5);
      ring.mesh.material.opacity = Math.max(0, 1 - k) * 0.8;
      if (ring.life <= 0) { ring.mesh.visible = false; }
    }
    this.rings = this.rings.filter(r => r.life > 0);

    for (const e of this.enemies) {
      if (e.removed) continue;
      if (e.flash > 0) e.flash -= dt;
      e.armorMat.emissive.setHex(0xff2a10);
      e.armorMat.emissiveIntensity = e.flash > 0 ? (e.flash / 0.12) * 1.6 : 0;
      if (e.visorGlow) {
        const pulse = 0.65 + Math.sin(time * 4 + e.walkPhase) * 0.18;
        e.visorGlow.material.opacity = e.state === 'dead' ? 0 : pulse;
      }

      if (e.state === 'dead') {
        e.deathTime += dt;
        const t = Math.min(1, e.deathTime / 0.65);
        e.group.rotation.z = -t * Math.PI * 0.52;
        e.group.position.y = -Math.max(0, e.deathTime - 1.4) * 0.8;
        if (e.deathTime > 0.15) {
          const fade = clamp(1 - (e.deathTime - 0.15) / 1.8, 0, 1);
          for (const m of e.materials) { m.transparent = true; m.opacity = fade; }
          if (e.visorGlow) e.visorGlow.material.opacity = fade * 0.6;
        }
        if (e.deathTime > 2.2) {
          this.scene.remove(e.group);
          e.removed = true;
        }
        continue;
      }

      if (e.state === 'spawn') {
        e.spawnTime += dt;
        const k = clamp(e.spawnTime / 0.75, 0, 1);
        const ease = 1 - Math.pow(1 - k, 3);
        e.group.position.y = lerp(-2.4, 0, ease);
        e.group.rotation.y += dt * 2;
        if (k >= 1) {
          e.state = 'active';
          e.group.position.y = 0;
          e.group.rotation.y = Math.atan2(playerPos.x - e.pos.x, playerPos.z - e.pos.z);
        }
        continue;
      }

      // ------------------------------------------------------------ active
      const dx = playerPos.x - e.pos.x;
      const dz = playerPos.z - e.pos.z;
      const dist = Math.hypot(dx, dz);
      e.targetYaw = Math.atan2(dx, dz);
      const turn = angleDelta(e.yaw, e.targetYaw);
      e.yaw += turn * Math.min(1, dt * 5.5);
      e.group.rotation.y = e.yaw;

      const from = _v1.set(e.pos.x, 1.35 * e.scale, e.pos.z);
      const los = this.hasLOS(from, playerChest, colliders);

      // movement
      let moveX = 0, moveZ = 0;
      const pref = e.type.preferred;
      const toPlayer = _v3.set(dx, 0, dz);
      if (dist > 0.01) toPlayer.multiplyScalar(1 / dist);
      e.strafeTimer -= dt;
      if (e.strafeTimer <= 0) {
        e.strafeTimer = rand(1.2, 3.2);
        e.strafeDir *= Math.random() > 0.35 ? 1 : -1;
      }
      let moveSpeed = e.type.speed;
      if (!los || dist > pref + 2.5) {
        moveX = toPlayer.x;
        moveZ = toPlayer.z;
      } else if (dist < pref - 2.0) {
        moveX = -toPlayer.x;
        moveZ = -toPlayer.z;
      } else {
        moveX = -toPlayer.z * e.strafeDir * 0.75;
        moveZ = toPlayer.x * e.strafeDir * 0.75;
        moveSpeed *= 0.55;
      }
      if (e.type.melee) {
        if (dist > 1.6) { moveX = toPlayer.x; moveZ = toPlayer.z; moveSpeed = e.type.speed; }
        else { moveX = 0; moveZ = 0; }
      }
      // separation
      for (const other of this.enemies) {
        if (other === e || other.removed || other.state === 'dead') continue;
        const ox = e.pos.x - other.pos.x;
        const oz = e.pos.z - other.pos.z;
        const od = Math.hypot(ox, oz);
        const minD = e.radius + other.radius + 0.5;
        if (od < minD && od > 0.001) {
          moveX += (ox / od) * (1 - od / minD) * 1.6;
          moveZ += (oz / od) * (1 - od / minD) * 1.6;
        }
      }
      const mlen = Math.hypot(moveX, moveZ);
      if (mlen > 0.001) {
        moveX /= mlen; moveZ /= mlen;
        const step = moveSpeed * dt;
        e.pos.x += moveX * step;
        e.pos.z += moveZ * step;
        e.walkAmount = lerp(e.walkAmount, 1, dt * 8);
      } else {
        e.walkAmount = lerp(e.walkAmount, 0, dt * 8);
      }
      // resolve collisions
      for (const c of colliders) {
        if (e.pos.y + 0.2 > c.maxY) continue;
        const r = resolveCircleBox(e.pos.x, e.pos.z, e.radius, c);
        if (r) { e.pos.x = r.x; e.pos.z = r.z; }
      }
      e.pos.x = clamp(e.pos.x, -42.4, 42.4);
      e.pos.z = clamp(e.pos.z, -42.4, 42.4);
      e.group.position.x = e.pos.x;
      e.group.position.z = e.pos.z;
      e.group.position.y = 0;

      // walk animation
      e.walkPhase += dt * (2.4 + moveSpeed * 0.85) * (0.35 + e.walkAmount);
      const sw = Math.sin(e.walkPhase) * 0.62 * e.walkAmount;
      const sw2 = Math.sin(e.walkPhase + Math.PI) * 0.62 * e.walkAmount;
      e.limbs.leftLeg.rotation.x = sw;
      e.limbs.rightLeg.rotation.x = sw2;
      e.limbs.leftKnee.rotation.x = Math.max(0, -sw) * 0.7;
      e.limbs.rightKnee.rotation.x = Math.max(0, -sw2) * 0.7;
      if (e.type.melee) {
        e.limbs.leftArm.rotation.x = -0.7 + Math.sin(time * 8) * 0.1;
        e.limbs.rightArm.rotation.x = -0.7 - Math.sin(time * 8) * 0.1;
        e.limbs.leftArm.rotation.z = 0.25;
        e.limbs.rightArm.rotation.z = -0.25;
      } else {
        e.limbs.leftArm.rotation.x = -0.55 + sw2 * 0.35;
        e.limbs.rightArm.rotation.x = -0.55 + sw * 0.35;
        e.limbs.leftArm.rotation.z = 0.12;
        e.limbs.rightArm.rotation.z = -0.12;
      }
      e.limbs.leftElbow.rotation.x = -0.35;
      e.limbs.rightElbow.rotation.x = -0.35;

      // attack
      e.fireTimer -= dt;
      if (e.burstLeft > 0) {
        e.burstTimer -= dt;
        if (e.burstTimer <= 0) {
          this.fire(e, player, playerChest, los, dist);
          e.burstLeft--;
          e.burstTimer = 0.11;
        }
      } else if (e.fireTimer <= 0 && los && dist < e.type.range) {
        if (e.type.melee) {
          if (dist < 2.1) {
            this.melee(e, player, dist);
            e.fireTimer = e.type.fireRate;
          } else {
            e.fireTimer = 0.2;
          }
        } else {
          e.burstLeft = e.type.burst || 1;
          e.burstTimer = 0;
          e.fireTimer = e.type.fireRate * rand(0.85, 1.2);
        }
      } else if (e.fireTimer <= 0) {
        e.fireTimer = 0.3;
      }
    }
    this.enemies = this.enemies.filter(e => !e.removed);
  }

  fire(e, player, playerChest, los, dist) {
    const muzzlePos = e.muzzle.getWorldPosition(new THREE.Vector3());
    const accuracy = clamp(1.12 - dist / 55, 0.28, 0.92) * e.type.accuracy;
    const hit = Math.random() < accuracy && los;
    const target = playerChest.clone();
    if (!hit) {
      target.x += rand(-2.4, 2.4);
      target.y += rand(-1.2, 1.6);
      target.z += rand(-2.4, 2.4);
    } else {
      target.x += rand(-0.12, 0.12);
      target.y += rand(-0.18, 0.18);
      target.z += rand(-0.12, 0.12);
    }
    this.effects.tracer(muzzlePos, target, 0xff8a50);
    this.effects.muzzleFlash(muzzlePos, 0.55, 0xff8a40);
    this.audio.shot('enemy', 0);
    if (hit) {
      const dmg = e.type.damage * (e.type.boss ? 1.15 : 1);
      this.callbacks.onPlayerDamage?.(dmg, e.pos.clone(), e.typeName);
    }
    this.callbacks.onEnemyShoot?.(e, muzzlePos, target);
  }

  melee(e, player, dist) {
    this.effects.spawnSparks(new THREE.Vector3(e.pos.x, 1.1, e.pos.z), new THREE.Vector3(0, 0.4, 1), 8, new THREE.Color(0xff7a30), 3, 0.09, 0.4);
    this.callbacks.onPlayerDamage?.(e.type.damage, e.pos.clone(), 'melee');
    this.callbacks.onEnemyMelee?.(e);
    e.flash = 0.08;
  }

  raycast(origin, dir, maxDist, colliders) {
    let wallT = maxDist;
    for (const c of colliders) {
      const t = rayAABB(origin, dir, c);
      if (t < wallT) wallT = t;
    }
    let best = null;
    for (const e of this.enemies) {
      if (e.state === 'dead' || e.state === 'spawn') continue;
      const s = e.scale;
      const headCenter = new THREE.Vector3(e.pos.x, 1.71 * s, e.pos.z);
      const headT = raySphere(origin, dir, headCenter, 0.2 * s);
      const bodyT = rayCapsule(origin, dir, new THREE.Vector3(e.pos.x, 0.62 * s, e.pos.z), 0.95 * s, 0.34 * s);
      let t = Infinity, head = false;
      if (headT < t) { t = headT; head = true; }
      if (bodyT < t) { t = bodyT; head = false; }
      if (t < wallT && t < maxDist && (!best || t < best.t)) {
        best = { enemy: e, t, headshot: head, point: origin.clone().addScaledVector(dir, t) };
      }
    }
    if (best) {
      best.normal = dir.clone().negate();
      return best;
    }
    if (wallT < maxDist) {
      const point = origin.clone().addScaledVector(dir, wallT);
      const normal = this.estimateNormal(point, dir);
      return { wall: true, t: wallT, point, normal };
    }
    return null;
  }

  estimateNormal(point, dir) {
    // pick the axis with the smallest overshoot relative to the hit point
    const n = dir.clone().negate();
    if (Math.abs(n.x) > Math.abs(n.y) && Math.abs(n.x) > Math.abs(n.z)) return new THREE.Vector3(Math.sign(n.x), 0, 0);
    if (Math.abs(n.z) > Math.abs(n.y)) return new THREE.Vector3(0, 0, Math.sign(n.z));
    return new THREE.Vector3(0, Math.sign(n.y) || 1, 0);
  }

  damage(e, amount, headshot, point, dir) {
    if (!e || e.state === 'dead' || e.state === 'spawn') return false;
    const dmg = amount * (headshot ? 2.35 : 1);
    e.hp -= dmg;
    e.flash = 0.12;
    e.alert = 1;
    this.effects.spawnBlood(point, dir, headshot ? 18 : 9);
    if (headshot) this.effects.spawnSparks(point, dir, 6, new THREE.Color(0xffd080), 3.5, 0.06, 0.4);
    if (e.hp <= 0) {
      this.kill(e, headshot);
      return true;
    }
    return false;
  }

  kill(e, headshot) {
    e.state = 'dead';
    e.deathTime = 0;
    e.hp = 0;
    e.group.position.y = 0;
    this.effects.spawnBlood(new THREE.Vector3(e.pos.x, 1.1, e.pos.z), null, 22);
    this.effects.spawnSparks(new THREE.Vector3(e.pos.x, 1.2, e.pos.z), new THREE.Vector3(0, 1, 0), 14, new THREE.Color(e.type.trim), 4, 0.1, 0.6);
    this.callbacks.onDeath?.(e, headshot);
  }

  clear() {
    for (const e of this.enemies) {
      this.scene.remove(e.group);
      e.removed = true;
    }
    this.enemies = [];
    for (const r of this.rings) { this.scene.remove(r.mesh); }
    this.rings = [];
  }
}

import * as THREE from 'three';
import { clamp, lerp, damp, resolveCircleBox } from './utils.js';

const _fwd = new THREE.Vector3();
const _right = new THREE.Vector3();

export class Player {
  constructor(camera, world, callbacks = {}) {
    this.camera = camera;
    this.world = world;
    this.callbacks = callbacks;
    this.position = new THREE.Vector3(world.playerSpawn.x, 0, world.playerSpawn.z);
    this.yaw = world.playerSpawn.yaw;
    this.pitch = -0.04;
    this.radius = 0.38;
    this.standEye = 1.72;
    this.crouchEye = 1.12;
    this.eyeHeight = this.standEye;
    this.velocityY = 0;
    this.grounded = true;
    this.crouching = false;
    this.sprinting = false;
    this.health = 100;
    this.maxHealth = 100;
    this.stamina = 1;
    this.speed = 0;
    this.bobPhase = 0;
    this.bobAmount = 0;
    this.shake = 0;
    this.shakeTime = 0;
    this.damageFlash = 0;
    this.lastDamageAt = -99;
    this.dead = false;
    this.sensitivity = 1;
    this.invertY = false;
    this.footstepTimer = 0;
    this.stepIndex = 0;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.recoilVelPitch = 0;
    this.recoilVelYaw = 0;
    this.time = 0;
    this.landImpact = 0;
    this._camPos = new THREE.Vector3();
  }

  reset(spawn) {
    this.position.set(spawn.x, 0, spawn.z);
    this.yaw = spawn.yaw || 0;
    this.pitch = -0.04;
    this.velocityY = 0;
    this.grounded = true;
    this.health = this.maxHealth;
    this.stamina = 1;
    this.dead = false;
    this.shake = 0;
    this.damageFlash = 0;
    this.lastDamageAt = -99;
    this.eyeHeight = this.standEye;
    this.recoilPitch = this.recoilYaw = 0;
    this.recoilVelPitch = this.recoilVelYaw = 0;
  }

  look(dx, dy) {
    if (this.dead) return;
    const s = 0.0022 * this.sensitivity;
    this.yaw -= dx * s;
    this.pitch -= dy * s * (this.invertY ? -1 : 1);
    this.pitch = clamp(this.pitch, -1.48, 1.42);
    if (this.yaw > Math.PI) this.yaw -= Math.PI * 2;
    if (this.yaw < -Math.PI) this.yaw += Math.PI * 2;
  }

  addRecoil(pitch, yaw) {
    this.recoilVelPitch -= pitch;
    this.recoilVelYaw += yaw;
  }

  takeDamage(amount, sourcePos, kind = 'shot') {
    if (this.dead) return;
    this.health = Math.max(0, this.health - amount);
    this.lastDamageAt = this.time;
    this.damageFlash = 1;
    this.shake = Math.min(1.4, this.shake + 0.5 + amount * 0.025);
    if (sourcePos) {
      const dx = sourcePos.x - this.position.x;
      const dz = sourcePos.z - this.position.z;
      const angle = Math.atan2(dx, dz);
      this.callbacks.onDamage?.(amount, angle, kind);
    } else {
      this.callbacks.onDamage?.(amount, 0, kind);
    }
    if (this.health <= 0) {
      this.dead = true;
      this.callbacks.onDeath?.();
    }
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount);
    this.callbacks.onHeal?.(amount);
  }

  update(dt, input) {
    if (this.dead) {
      // death camera drop
      this.eyeHeight = damp(this.eyeHeight, 0.35, 4, dt);
      this.updateCamera(dt, 0);
      return;
    }
    this.time += dt;

    // recoil spring
    this.recoilPitch += this.recoilVelPitch * dt;
    this.recoilYaw += this.recoilVelYaw * dt;
    this.recoilVelPitch *= Math.pow(0.001, dt);
    this.recoilVelYaw *= Math.pow(0.001, dt);
    this.recoilPitch = damp(this.recoilPitch, 0, 12, dt);
    this.recoilYaw = damp(this.recoilYaw, 0, 12, dt);

    // crouch / sprint
    const wantCrouch = input.crouch;
    this.crouching = wantCrouch;
    const moving = input.forward || input.back || input.left || input.right;
    this.sprinting = input.sprint && !this.crouching && input.forward && this.stamina > 0.02 && !input.fire;
    if (this.sprinting) {
      this.stamina = Math.max(0, this.stamina - dt * 0.22);
    } else {
      this.stamina = Math.min(1, this.stamina + dt * (moving ? 0.12 : 0.2));
    }

    const targetEye = this.crouching ? this.crouchEye : this.standEye;
    this.eyeHeight = damp(this.eyeHeight, targetEye, 12, dt);

    // movement vectors
    const speedBase = this.crouching ? 2.7 : this.sprinting ? 8.4 : 5.3;
    _fwd.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    _right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    let mx = 0, mz = 0;
    if (input.forward) { mx += _fwd.x; mz += _fwd.z; }
    if (input.back) { mx -= _fwd.x; mz -= _fwd.z; }
    if (input.right) { mx += _right.x; mz += _right.z; }
    if (input.left) { mx -= _right.x; mz -= _right.z; }
    const len = Math.hypot(mx, mz);
    if (len > 0.001) { mx /= len; mz /= len; }
    this.speed = len > 0 ? speedBase : 0;

    // horizontal movement with axis-separated collision
    if (len > 0.001) {
      const step = speedBase * dt;
      this.position.x += mx * step;
      this.resolveCollisions('x');
      this.position.z += mz * step;
      this.resolveCollisions('z');
    }
    this.position.x = clamp(this.position.x, -42.5, 42.5);
    this.position.z = clamp(this.position.z, -42.5, 42.5);

    // jump / gravity
    if (input.jump && this.grounded && !this.crouching) {
      this.velocityY = 7.0;
      this.grounded = false;
      this.callbacks.onJump?.();
    }
    this.velocityY -= 22 * dt;
    this.position.y += this.velocityY * dt;
    if (this.position.y <= 0) {
      if (!this.grounded && this.velocityY < -4) {
        this.landImpact = clamp(-this.velocityY / 12, 0, 1);
        this.shake = Math.min(1, this.shake + this.landImpact * 0.25);
        this.callbacks.onLand?.(this.landImpact);
      }
      this.position.y = 0;
      this.velocityY = 0;
      this.grounded = true;
    }

    // bob
    if (this.grounded && len > 0.001) {
      this.bobPhase += dt * (this.sprinting ? 13 : 9.5);
      this.bobAmount = damp(this.bobAmount, this.sprinting ? 1.25 : 0.8, 8, dt);
      this.footstepTimer -= dt;
      if (this.footstepTimer <= 0) {
        this.footstepTimer = this.sprinting ? 0.3 : 0.44;
        this.stepIndex++;
        this.callbacks.onFootstep?.(this.stepIndex, this.sprinting);
      }
    } else {
      this.bobAmount = damp(this.bobAmount, 0, 8, dt);
    }
    this.landImpact = damp(this.landImpact, 0, 6, dt);

    // health regen after 6.5s
    if (this.time - this.lastDamageAt > 6.5 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + dt * 9);
    }
    this.damageFlash = damp(this.damageFlash, 0, 5, dt);

    this.updateCamera(dt, len);
  }

  resolveCollisions(axis) {
    const feet = this.position.y;
    for (const c of this.world.colliders) {
      if (feet > c.maxY - 0.06) continue;
      const r = resolveCircleBox(this.position.x, this.position.z, this.radius, c);
      if (r) {
        if (axis === 'x') this.position.x = r.x;
        else this.position.z = r.z;
      }
    }
  }

  updateCamera(dt, moving) {
    this.shakeTime += dt;
    const shake = this.shake;
    this.shake = damp(this.shake, 0, 7, dt);
    const sx = (Math.sin(this.shakeTime * 63) + Math.sin(this.shakeTime * 41)) * 0.5 * shake * 0.055;
    const sy = (Math.sin(this.shakeTime * 71) + Math.cos(this.shakeTime * 47)) * 0.5 * shake * 0.045;
    const bob = this.bobAmount * 0.035;
    const bx = Math.sin(this.bobPhase) * bob;
    const by = Math.abs(Math.cos(this.bobPhase)) * bob * 0.75;
    this._camPos.set(this.position.x + bx, this.position.y + this.eyeHeight + by - this.landImpact * 0.12, this.position.z);
    this.camera.position.copy(this._camPos);
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.y = this.yaw + this.recoilYaw + sx * 0.2;
    this.camera.rotation.x = this.pitch + this.recoilPitch + sy;
    this.camera.rotation.z = -bx * 0.12 + sx * 0.4;
  }

  getForward(out = new THREE.Vector3()) {
    const cp = Math.cos(this.pitch);
    out.set(-Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp);
    return out;
  }

  getEye(out = new THREE.Vector3()) {
    return out.set(this.position.x, this.position.y + this.eyeHeight, this.position.z);
  }
}

import * as THREE from 'three';
import { clamp, lerp, damp, rand } from './utils.js';

const _v = new THREE.Vector3();
const _right = new THREE.Vector3();
const _up = new THREE.Vector3();
const _dir = new THREE.Vector3();
const _muzzle = new THREE.Vector3();
const _eye = new THREE.Vector3();

const WEAPONS = [
  {
    id: 'rifle', name: 'MK-17 VANGUARD', mode: 'AUTO', fireMode: 'FULL AUTO', slot: '1 / 2',
    magSize: 30, reserveMax: 210, damage: 23, rpm: 720, reload: 1.85, auto: true,
    spread: 0.0075, adsSpread: 0.0016, moveSpread: 0.008, recoil: 0.0125, recoilYaw: 0.0028,
    range: 110, color: 0xffc070, adsFov: 54,
  },
  {
    id: 'pistol', name: 'P-9 SIDEWINDER', mode: 'SEMI', fireMode: 'SEMI AUTO', slot: '2 / 2',
    magSize: 12, reserveMax: 84, damage: 36, rpm: 330, reload: 1.55, auto: false,
    spread: 0.009, adsSpread: 0.0022, moveSpread: 0.01, recoil: 0.019, recoilYaw: 0.004,
    range: 80, color: 0x9fe8ff, adsFov: 58,
  },
];

export class WeaponSystem {
  constructor({ camera, scene, player, enemies, world, effects, audio, T, callbacks = {} }) {
    this.camera = camera;
    this.scene = scene;
    this.player = player;
    this.enemies = enemies;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.T = T;
    this.callbacks = callbacks;
    this.weapons = WEAPONS.map((def) => ({ def, mag: def.magSize, reserve: Math.floor(def.reserveMax * 0.7) }));
    this.index = 0;
    this.cooldown = 0;
    this.reloading = false;
    this.reloadTime = 0;
    this.triggerPrev = false;
    this.ads = false;
    this.adsAmount = 0;
    this.muzzleTimer = 0;
    this.switchTimer = 0;
    this.pendingIndex = -1;
    this.shots = 0;
    this.hits = 0;
    this.headshots = 0;
    this.time = 0;
    this.swayX = 0;
    this.swayY = 0;
    this.lastYaw = player.yaw;
    this.lastPitch = player.pitch;
    this.kick = 0;
    this.shellTimer = 0;

    this.group = new THREE.Group();
    this.group.position.set(0.3, -0.26, -0.52);
    camera.add(this.group);
    scene.add(camera);

    this.models = [this.buildRifle(), this.buildPistol()];
    for (const m of this.models) this.group.add(m);
    this.models[1].visible = false;

    this.muzzleLight = new THREE.PointLight(0xffa040, 0, 5, 2);
    this.muzzleLight.position.set(0, 0.02, -0.85);
    this.group.add(this.muzzleLight);

    this.flashSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: T.flash, color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
    }));
    this.flashSprite.scale.set(0.55, 0.55, 1);
    this.flashSprite.position.set(0, 0.02, -0.95);
    this.flashSprite.visible = false;
    this.group.add(this.flashSprite);

    this.onAmmo();
    this.onWeapon();
  }

  // --------------------------------------------------------------- models
  makeMats() {
    return {
      metal: new THREE.MeshStandardMaterial({ color: 0x20262a, roughness: 0.32, metalness: 0.88 }),
      dark: new THREE.MeshStandardMaterial({ color: 0x0c0f11, roughness: 0.45, metalness: 0.8 }),
      polymer: new THREE.MeshStandardMaterial({ color: 0x2b3134, roughness: 0.72, metalness: 0.12 }),
      accent: new THREE.MeshStandardMaterial({ color: 0x161a1c, emissive: 0x53d8ff, emissiveIntensity: 1.4, roughness: 0.35, metalness: 0.6 }),
      brass: new THREE.MeshStandardMaterial({ color: 0xba8f4a, roughness: 0.3, metalness: 0.95 }),
      glove: new THREE.MeshStandardMaterial({ color: 0x24272a, roughness: 0.86, metalness: 0.05 }),
      gloveLight: new THREE.MeshStandardMaterial({ color: 0x3a3f42, roughness: 0.8, metalness: 0.05 }),
      lens: new THREE.MeshStandardMaterial({ color: 0x0a1a20, emissive: 0x67e8ff, emissiveIntensity: 1.6, roughness: 0.1, metalness: 0.5 }),
    };
  }

  addBox(parent, w, h, d, mat, x, y, z, rx = 0, ry = 0, rz = 0) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z);
    m.rotation.set(rx, ry, rz);
    parent.add(m);
    return m;
  }

  addCyl(parent, r1, r2, len, mat, x, y, z, rx = 0, ry = 0, rz = 0, seg = 10) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, len, seg), mat);
    m.position.set(x, y, z);
    m.rotation.set(rx, ry, rz);
    parent.add(m);
    return m;
  }

  buildRifle() {
    const g = new THREE.Group();
    const M = this.makeMats();
    // receiver
    this.addBox(g, 0.062, 0.085, 0.4, M.metal, 0, 0, 0.02);
    this.addBox(g, 0.05, 0.028, 0.36, M.dark, 0, 0.055, 0.01);
    // handguard
    this.addBox(g, 0.052, 0.062, 0.32, M.polymer, 0, 0.005, -0.34);
    for (let i = 0; i < 5; i++) this.addBox(g, 0.058, 0.012, 0.025, M.dark, 0, 0.04, -0.24 - i * 0.055);
    // barrel + suppressor
    this.addCyl(g, 0.012, 0.012, 0.28, M.dark, 0, 0.01, -0.62, Math.PI / 2);
    this.addCyl(g, 0.026, 0.024, 0.19, M.metal, 0, 0.01, -0.83, Math.PI / 2);
    this.addCyl(g, 0.028, 0.028, 0.02, M.accent, 0, 0.01, -0.93, Math.PI / 2);
    // stock
    this.addBox(g, 0.05, 0.095, 0.26, M.polymer, 0, -0.012, 0.33);
    this.addBox(g, 0.045, 0.13, 0.05, M.dark, 0, -0.03, 0.46);
    this.addBox(g, 0.03, 0.05, 0.16, M.dark, 0, 0.06, 0.28);
    // magazine
    const mag = this.addBox(g, 0.045, 0.18, 0.09, M.polymer, 0, -0.13, 0.01, 0.18);
    // grip
    this.addBox(g, 0.042, 0.15, 0.055, M.polymer, 0, -0.115, 0.17, -0.28);
    // trigger guard
    this.addBox(g, 0.02, 0.06, 0.09, M.dark, 0, -0.075, 0.1);
    // optic
    this.addBox(g, 0.05, 0.045, 0.17, M.dark, 0, 0.085, -0.03);
    this.addCyl(g, 0.026, 0.026, 0.15, M.metal, 0, 0.095, -0.03, Math.PI / 2);
    const lens = this.addCyl(g, 0.022, 0.022, 0.012, M.lens, 0, 0.095, -0.11, Math.PI / 2);
    // iron sights
    this.addBox(g, 0.012, 0.045, 0.012, M.dark, 0, 0.085, -0.52);
    this.addBox(g, 0.03, 0.012, 0.012, M.dark, 0, 0.085, -0.52);
    // charging handle
    this.addBox(g, 0.07, 0.02, 0.02, M.dark, 0.04, 0.03, 0.1);
    // hands
    const rightHand = new THREE.Group();
    rightHand.position.set(0.005, -0.11, 0.18);
    g.add(rightHand);
    this.addBox(rightHand, 0.075, 0.09, 0.1, M.glove, 0, -0.01, 0, -0.25);
    for (let i = 0; i < 4; i++) this.addBox(rightHand, 0.018, 0.065, 0.02, M.gloveLight, 0.038, 0.015, -0.04 + i * 0.024, -0.4);
    const leftHand = new THREE.Group();
    leftHand.position.set(0.005, -0.075, -0.33);
    g.add(leftHand);
    this.addBox(leftHand, 0.085, 0.07, 0.12, M.glove, 0, 0, 0);
    for (let i = 0; i < 4; i++) this.addBox(leftHand, 0.02, 0.055, 0.02, M.gloveLight, 0.04, 0.035, -0.045 + i * 0.028, 0.3);
    // forearm hints
    this.addBox(g, 0.07, 0.07, 0.26, M.glove, 0.04, -0.18, 0.3, 0.35, 0.25);
    this.addBox(g, 0.07, 0.07, 0.24, M.glove, -0.02, -0.16, -0.52, -0.25, -0.2);
    // muzzle marker
    const muzzle = new THREE.Object3D();
    muzzle.position.set(0, 0.01, -0.95);
    g.add(muzzle);
    g.userData.muzzle = muzzle;
    g.userData.mag = mag;
    g.userData.lens = lens;
    return g;
  }

  buildPistol() {
    const g = new THREE.Group();
    const M = this.makeMats();
    this.addBox(g, 0.045, 0.055, 0.24, M.metal, 0, 0.02, -0.02);
    this.addBox(g, 0.04, 0.03, 0.22, M.dark, 0, 0.055, -0.02);
    this.addCyl(g, 0.014, 0.014, 0.07, M.dark, 0, 0.02, -0.16, Math.PI / 2);
    this.addCyl(g, 0.019, 0.019, 0.055, M.metal, 0, 0.02, -0.21, Math.PI / 2);
    // grip
    this.addBox(g, 0.042, 0.16, 0.07, M.polymer, 0, -0.09, 0.08, -0.2);
    // trigger guard
    this.addBox(g, 0.015, 0.055, 0.07, M.dark, 0, -0.055, 0.015);
    // sights
    this.addBox(g, 0.008, 0.02, 0.008, M.accent, 0, 0.075, -0.11);
    this.addBox(g, 0.026, 0.01, 0.01, M.dark, 0, 0.075, 0.09);
    // hands
    const hand = new THREE.Group();
    hand.position.set(0, -0.09, 0.09);
    g.add(hand);
    this.addBox(hand, 0.08, 0.09, 0.1, M.glove, 0, 0, 0, -0.2);
    for (let i = 0; i < 4; i++) this.addBox(hand, 0.018, 0.06, 0.02, M.gloveLight, 0.04, 0.015, -0.04 + i * 0.024, -0.3);
    this.addBox(g, 0.07, 0.07, 0.24, M.glove, 0.03, -0.18, 0.24, 0.3, 0.25);
    const muzzle = new THREE.Object3D();
    muzzle.position.set(0, 0.02, -0.24);
    g.add(muzzle);
    g.userData.muzzle = muzzle;
    g.userData.mag = null;
    return g;
  }

  // ------------------------------------------------------------- callbacks
  onAmmo() {
    const w = this.weapons[this.index];
    this.callbacks.onAmmo?.(w.mag, w.reserve, w.def.magSize);
  }
  onWeapon() {
    const w = this.weapons[this.index];
    this.callbacks.onWeapon?.(w.def, w.mag, w.reserve);
  }

  get current() { return this.weapons[this.index]; }

  startReload() {
    if (this.reloading || this.switchTimer > 0) return;
    const w = this.current;
    if (w.mag >= w.def.magSize || w.reserve <= 0) return;
    this.reloading = true;
    this.reloadTime = 0;
    this.audio.reload(0);
    setTimeout(() => { if (this.reloading) this.audio.reload(1); }, 450);
    this.callbacks.onReloadStart?.(w.def.reload);
  }

  cancelReload() {
    this.reloading = false;
    this.reloadTime = 0;
    this.callbacks.onReloadCancel?.();
  }

  switchTo(index) {
    if (index === this.index || this.switchTimer > 0) return;
    this.pendingIndex = index;
    this.switchTimer = 0.42;
    this.cancelReload();
    this.audio.swap();
  }

  update(dt, input) {
    this.time += dt;
    const w = this.current;
    const def = w.def;
    this.cooldown = Math.max(0, this.cooldown - dt);

    // ads
    const wantAds = input.aim && !this.reloading && this.switchTimer <= 0;
    this.ads = wantAds;
    this.adsAmount = damp(this.adsAmount, wantAds ? 1 : 0, 13, dt);

    // switching
    if (this.switchTimer > 0) {
      this.switchTimer -= dt;
      if (this.pendingIndex >= 0 && this.switchTimer <= 0.21) {
        this.models[this.index].visible = false;
        this.index = this.pendingIndex;
        this.models[this.index].visible = true;
        this.pendingIndex = -1;
        this.onAmmo();
        this.onWeapon();
      }
    }

    // reload
    if (this.reloading) {
      this.reloadTime += dt;
      if (this.reloadTime >= def.reload) {
        const need = def.magSize - w.mag;
        const take = Math.min(need, w.reserve);
        w.mag += take;
        w.reserve -= take;
        this.reloading = false;
        this.reloadTime = 0;
        this.onAmmo();
        this.callbacks.onReloadEnd?.();
      }
    }

    // trigger
    const trigger = input.fire;
    if (trigger && !this.triggerPrev && !this.ads) {
      // first click can also start ADS if right mouse is not pressed; handled elsewhere
    }
    if (trigger && !this.reloading && this.switchTimer <= 0) {
      if (def.auto || !this.triggerPrev) this.tryFire();
    }
    this.triggerPrev = trigger;

    if (input.reload && !this.reloading) this.startReload();

    // muzzle flash
    if (this.muzzleTimer > 0) {
      this.muzzleTimer -= dt;
      const k = Math.max(0, this.muzzleTimer / 0.055);
      this.flashSprite.material.opacity = k;
      this.flashSprite.visible = true;
      this.flashSprite.material.rotation = rand(0, Math.PI * 2);
      this.flashSprite.scale.setScalar(0.45 + rand(0, 0.15));
      this.muzzleLight.intensity = k * 8;
      if (this.muzzleTimer <= 0) {
        this.flashSprite.visible = false;
        this.muzzleLight.intensity = 0;
      }
    }

    // sway from look delta
    const dyaw = this.player.yaw - this.lastYaw;
    const dpitch = this.player.pitch - this.lastPitch;
    this.lastYaw = this.player.yaw;
    this.lastPitch = this.player.pitch;
    this.swayX = damp(this.swayX, clamp(-dyaw * 3.2, -0.06, 0.06), 10, dt);
    this.swayY = damp(this.swayY, clamp(dpitch * 3.2, -0.05, 0.05), 10, dt);

    // recoil kick (visual)
    this.kick = damp(this.kick, 0, 18, dt);

    // weapon position
    const bob = this.player.bobAmount;
    const bobX = Math.sin(this.player.bobPhase) * 0.012 * bob;
    const bobY = Math.abs(Math.cos(this.player.bobPhase)) * 0.01 * bob;
    const ads = this.adsAmount;
    const baseX = lerp(0.3, 0, ads);
    const baseY = lerp(-0.26, -0.145, ads);
    const baseZ = lerp(-0.52, -0.42, ads);
    let x = baseX + bobX + this.swayX * (1 - ads * 0.7);
    let y = baseY + bobY + this.swayY * (1 - ads * 0.7) - this.kick * 0.02;
    let z = baseZ + this.kick * 0.08;
    let rx = this.kick * 0.28 + this.swayY * 0.5;
    let ry = -this.swayX * 0.7;
    let rz = bobX * 0.5;
    // reload dip
    if (this.reloading) {
      const t = this.reloadTime / def.reload;
      const dip = Math.sin(Math.min(1, t * 1.05) * Math.PI);
      y -= dip * 0.15;
      rx += dip * 0.55;
      rz += dip * 0.18;
      const mag = this.models[this.index].userData.mag;
      if (mag) {
        const drop = t > 0.35 && t < 0.78 ? Math.sin(((t - 0.35) / 0.43) * Math.PI) * 0.22 : 0;
        mag.position.y = -0.13 - drop;
        mag.visible = !(t > 0.4 && t < 0.7);
      }
    } else {
      const mag = this.models[this.index].userData.mag;
      if (mag) { mag.position.y = -0.13; mag.visible = true; }
    }
    // switch dip
    if (this.switchTimer > 0) {
      const t = 1 - Math.abs(this.switchTimer / 0.42 - 0.5) * 2;
      y -= Math.sin(t * Math.PI) * 0.2;
      rx += Math.sin(t * Math.PI) * 0.6;
    }
    this.group.position.set(x, y, z);
    this.group.rotation.set(rx, ry, rz);
    // model scale slightly down in ads for framing
    for (const m of this.models) m.scale.setScalar(lerp(1, 0.92, ads));

    // camera fov
    const targetFov = lerp(76, def.adsFov, ads);
    this.camera.fov = damp(this.camera.fov, targetFov, 12, dt);
    this.camera.updateProjectionMatrix();

    // crosshair spread px
    const moveFactor = clamp(this.player.speed / 8.4, 0, 1);
    const spread = lerp(def.spread, def.adsSpread, ads) + def.moveSpread * moveFactor * (1 - ads * 0.7) + this.kick * 0.12;
    const px = clamp(spread * 1800, 2, 32);
    this.callbacks.onSpread?.(px, this.adsAmount, this.reloading ? this.reloadTime / def.reload : 0, this.reloading);

    // shell timer
    if (this.shellTimer > 0) this.shellTimer -= dt;
  }

  tryFire() {
    const w = this.current;
    const def = w.def;
    if (this.cooldown > 0) return;
    if (this.reloading || this.switchTimer > 0) return;
    if (w.mag <= 0) {
      this.audio.dryFire();
      this.cooldown = 0.3;
      this.startReload();
      return;
    }
    w.mag--;
    this.cooldown = 60 / def.rpm;
    this.shots++;
    this.kick = Math.min(1.6, this.kick + 1);
    this.muzzleTimer = 0.055;
    this.audio.shot(def.id === 'pistol' ? 'pistol' : 'rifle', 0);
    this.player.addRecoil(def.recoil, rand(-def.recoilYaw, def.recoilYaw));

    // muzzle world position
    const model = this.models[this.index];
    const muzzle = model.userData.muzzle;
    muzzle.getWorldPosition(_muzzle);
    this.flashSprite.position.set(muzzle.position.x, muzzle.position.y, muzzle.position.z - 0.02);

    // aim ray with spread
    this.player.getForward(_dir);
    _right.crossVectors(_dir, new THREE.Vector3(0, 1, 0)).normalize();
    if (_right.lengthSq() < 0.01) _right.set(1, 0, 0);
    _up.crossVectors(_right, _dir).normalize();
    const moveFactor = clamp(this.player.speed / 8.4, 0, 1);
    const spread = lerp(def.spread, def.adsSpread, this.adsAmount) + def.moveSpread * moveFactor * (1 - this.adsAmount * 0.75);
    _dir.addScaledVector(_right, rand(-spread, spread));
    _dir.addScaledVector(_up, rand(-spread, spread));
    _dir.normalize();

    this.player.getEye(_eye);
    const hit = this.enemies.raycast(_eye, _dir, def.range, this.world.colliders);
    let end = _eye.clone().addScaledVector(_dir, def.range);
    let hitEnemy = false;
    let headshot = false;
    let killed = false;
    if (hit) {
      end = hit.point;
      if (hit.enemy) {
        hitEnemy = true;
        headshot = hit.headshot;
        this.hits++;
        if (headshot) this.headshots++;
        killed = this.enemies.damage(hit.enemy, def.damage, headshot, hit.point, _dir);
        this.effects.impact(hit.point, hit.normal, 'enemy');
        this.audio.hit(headshot);
      } else {
        this.effects.impact(hit.point, hit.normal, 'wall');
        this.audio.hit(false);
      }
    }
    this.effects.tracer(_muzzle, end, def.color);
    this.effects.muzzleFlash(_muzzle, def.id === 'pistol' ? 0.45 : 0.65, def.color);
    // eject shell
    if (this.shellTimer <= 0) {
      this.shellTimer = 0.1;
      const side = new THREE.Vector3(1, 0.4, 0).applyQuaternion(this.camera.quaternion);
      this.effects.shell(_muzzle.clone().addScaledVector(side, 0.12), side);
    }
    this.callbacks.onShot?.({ hit: hitEnemy, headshot, killed, ammo: w.mag, reserve: w.reserve, magSize: def.magSize });
    this.onAmmo();
  }

  reset() {
    for (const w of this.weapons) {
      w.mag = w.def.magSize;
      w.reserve = Math.floor(w.def.reserveMax * 0.7);
    }
    this.index = 0;
    this.models[0].visible = true;
    this.models[1].visible = false;
    this.reloading = false;
    this.reloadTime = 0;
    this.switchTimer = 0;
    this.pendingIndex = -1;
    this.cooldown = 0;
    this.shots = 0;
    this.hits = 0;
    this.headshots = 0;
    this.ads = false;
    this.adsAmount = 0;
    this.onAmmo();
    this.onWeapon();
  }
}

import { clamp, formatScore, formatTime } from './utils.js';

const $ = (id) => document.getElementById(id);

export class UI {
  constructor(callbacks = {}) {
    this.callbacks = callbacks;
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.settings = { sensitivity: 1, volume: 0.7, quality: this.isTouch ? 'medium' : 'high', invert: false };
    this.loadSettings();
    this.lastAmmo = { mag: -1, reserve: -1, max: -1 };
    this.lastWave = -1;
    this.lastEnemies = -1;
    this.lastScore = -1;
    this.lastKills = -1;
    this.lastAcc = -1;
    this.clockTimer = 0;
    this.toastTimer = null;
    this.waveTimer = null;
    this.els = {};
    const ids = [
      'loading', 'load-bar', 'load-status', 'menu', 'start-btn', 'best-score', 'menu-clock',
      'hud', 'wave-label', 'enemy-count', 'wave-pips', 'score', 'kills', 'accuracy', 'compass',
      'compass-heading', 'minimap', 'crosshair', 'hitmarker', 'killfeed', 'wave-banner', 'toast',
      'health-value', 'health-bar', 'health-state', 'stamina-bar', 'stamina-label', 'ammo-mag',
      'ammo-reserve', 'weapon-name', 'weapon-mode', 'fire-mode', 'weapon-slot', 'reload-bar',
      'damage-vignette', 'low-health', 'hit-flash', 'damage-dirs', 'hint', 'interact-prompt',
      'pause', 'pause-wave', 'pause-score', 'pause-kills', 'pause-acc', 'pause-fps',
      'result', 'result-kicker', 'result-title', 'result-sub', 'res-score', 'res-kills', 'res-heads',
      'res-acc', 'res-time', 'res-best', 'mobile-controls', 'rotate-notice', 'move-stick', 'move-knob',
      'look-zone', 'btn-fire', 'btn-reload', 'btn-jump', 'btn-sprint', 'btn-swap', 'btn-pause',
    ];
    for (const id of ids) this.els[id] = $(id);
    this.compassCtx = this.els.compass.getContext('2d');
    this.minimapCtx = this.els.minimap.getContext('2d');
    this.bind();
    this.applySettings(this.settings, true);
    this.updateClock();
    this.clockTimer = setInterval(() => this.updateClock(), 1000);
  }

  // ------------------------------------------------------------- settings
  loadSettings() {
    try {
      const saved = JSON.parse(localStorage.getItem('blacksite.settings') || 'null');
      if (saved) this.settings = { ...this.settings, ...saved };
    } catch {}
    try {
      const best = Number(localStorage.getItem('blacksite.best') || 0);
      this.els.bestScore.textContent = formatScore(best);
    } catch {}
  }

  saveSettings() {
    try { localStorage.setItem('blacksite.settings', JSON.stringify(this.settings)); } catch {}
  }

  applySettings(settings, initial = false) {
    this.settings = { ...this.settings, ...settings };
    for (const el of document.querySelectorAll('[data-setting]')) {
      const key = el.dataset.setting;
      if (!(key in this.settings)) continue;
      if (el.type === 'checkbox') el.checked = Boolean(this.settings[key]);
      else el.value = this.settings[key];
      if (el.type === 'range') {
        const pct = ((Number(el.value) - Number(el.min)) / (Number(el.max) - Number(el.min))) * 100;
        el.style.setProperty('--fill', `${pct}%`);
      }
    }
    for (const out of document.querySelectorAll('[data-out]')) {
      const key = out.dataset.out;
      if (key === 'volume') out.textContent = Math.round(Number(this.settings.volume) * 100);
      else if (key === 'sensitivity') out.textContent = Number(this.settings.sensitivity).toFixed(1);
    }
    if (!initial) this.callbacks.onSettings?.(this.settings);
  }

  bind() {
    for (const el of document.querySelectorAll('[data-setting]')) {
      el.addEventListener('input', () => {
        const key = el.dataset.setting;
        let value = el.type === 'checkbox' ? el.checked : el.type === 'range' ? Number(el.value) : el.value;
        if (key === 'quality') value = String(value);
        this.applySettings({ [key]: value });
        this.saveSettings();
      });
    }
    this.els['start-btn'].addEventListener('click', () => {
      this.callbacks.onStart?.();
    });
    $('resume-btn')?.addEventListener('click', () => this.callbacks.onResume?.());
    $('restart-btn')?.addEventListener('click', () => this.callbacks.onRestart?.());
    $('quit-btn')?.addEventListener('click', () => this.callbacks.onQuit?.());
    $('again-btn')?.addEventListener('click', () => this.callbacks.onAgain?.());
    $('menu-btn')?.addEventListener('click', () => this.callbacks.onMenu?.());
    this.els['btn-pause']?.addEventListener('click', (e) => { e.preventDefault(); this.callbacks.onPause?.(); });
    for (const id of ['resume-btn', 'restart-btn', 'quit-btn', 'again-btn', 'menu-btn', 'start-btn']) {
      const el = $(id);
      if (el) el.addEventListener('pointerenter', () => this.callbacks.onUIHover?.());
      if (el) el.addEventListener('pointerdown', () => this.callbacks.onUIClick?.());
    }
    // prevent browser gestures on the touch HUD
    for (const id of ['move-stick', 'look-zone', 'btn-fire', 'btn-reload', 'btn-jump', 'btn-sprint', 'btn-swap']) {
      const el = this.els[id];
      if (el) el.addEventListener('touchstart', (e) => { e.preventDefault(); }, { passive: false });
    }
  }

  // --------------------------------------------------------------- screens
  setLoading(pct, status) {
    this.els['load-bar'].style.width = `${clamp(pct, 0, 100)}%`;
    if (status) this.els['load-status'].textContent = status;
  }

  hideLoading() { this.els.loading.classList.add('hidden'); }
  showMenu() {
    this.els.menu.classList.remove('hidden');
    this.els.hud.classList.add('hidden');
    this.els.pause.classList.add('hidden');
    this.els.result.classList.add('hidden');
    this.els['mobile-controls'].classList.add('hidden');
    this.els['damage-vignette'].style.opacity = '0';
    this.els['low-health'].classList.remove('on');
  }
  showHUD() {
    this.els.menu.classList.add('hidden');
    this.els.hud.classList.remove('hidden');
    this.els.pause.classList.add('hidden');
    this.els.result.classList.add('hidden');
    if (this.isTouch) this.els['mobile-controls'].classList.remove('hidden');
  }
  showPause() { this.els.pause.classList.remove('hidden'); }
  hidePause() { this.els.pause.classList.add('hidden'); }
  showResult(win, stats) {
    this.els.hud.classList.add('hidden');
    this.els['mobile-controls'].classList.add('hidden');
    this.els.pause.classList.add('hidden');
    this.els.result.classList.remove('hidden');
    this.els.result.classList.toggle('lost', !win);
    this.els['result-kicker'].textContent = win ? 'MISSION COMPLETE' : 'MISSION FAILED';
    this.els['result-title'].textContent = win ? 'EXTRACTION SECURED' : 'OPERATIVE DOWN';
    this.els['result-sub'].textContent = win
      ? 'All five assault waves neutralized. The valley is quiet. Extraction is inbound.'
      : 'Your signal went dark. The compound remains under Sentinel control.';
    this.els['res-score'].textContent = formatScore(stats.score);
    this.els['res-kills'].textContent = stats.kills;
    this.els['res-heads'].textContent = stats.headshots;
    this.els['res-acc'].textContent = `${stats.accuracy}%`;
    this.els['res-time'].textContent = formatTime(stats.time);
    this.els['res-best'].textContent = formatScore(stats.best);
  }

  updateBest(best) {
    this.els['best-score'].textContent = formatScore(best);
  }

  updateClock() {
    const d = new Date();
    this.els['menu-clock'].textContent = d.toISOString().slice(11, 19);
  }

  // ------------------------------------------------------------------ HUD
  setWave(wave, total = 5, alive = 0) {
    if (wave !== this.lastWave) {
      this.lastWave = wave;
      this.els['wave-label'].textContent = `WAVE ${Math.min(wave, total)} / ${total}`;
      const pips = this.els['wave-pips'];
      pips.innerHTML = '';
      for (let i = 0; i < total; i++) {
        const p = document.createElement('i');
        if (i < wave - 1) p.className = 'done';
        else if (i === wave - 1) p.className = 'active';
        pips.appendChild(p);
      }
    }
    if (alive !== this.lastEnemies) {
      this.lastEnemies = alive;
      this.els['enemy-count'].textContent = `${alive} HOSTILE${alive === 1 ? '' : 'S'}`;
    }
  }

  setScore(score, kills, accuracy) {
    if (score !== this.lastScore) {
      this.lastScore = score;
      this.els.score.textContent = formatScore(score);
    }
    if (kills !== this.lastKills) {
      this.lastKills = kills;
      this.els.kills.textContent = `${kills} KILLS`;
    }
    if (accuracy !== this.lastAcc) {
      this.lastAcc = accuracy;
      this.els.accuracy.textContent = `${accuracy}% ACC`;
    }
  }

  setHealth(hp, max = 100, stamina = 1) {
    const v = Math.max(0, Math.round(hp));
    this.els['health-value'].textContent = v;
    const pct = clamp(hp / max, 0, 1) * 100;
    const bar = this.els['health-bar'];
    bar.style.width = `${pct}%`;
    bar.classList.toggle('mid', hp / max <= 0.6 && hp / max > 0.3);
    bar.classList.toggle('low', hp / max <= 0.3);
    const state = this.els['health-state'];
    if (hp <= 0) { state.textContent = 'CRITICAL'; state.classList.add('hurt'); }
    else if (hp / max <= 0.3) { state.textContent = 'CRITICAL'; state.classList.add('hurt'); }
    else if (hp / max <= 0.6) { state.textContent = 'DAMAGED'; state.classList.add('hurt'); }
    else { state.textContent = 'NOMINAL'; state.classList.remove('hurt'); }
    this.els['stamina-bar'].style.width = `${clamp(stamina, 0, 1) * 100}%`;
    this.els['stamina-label'].textContent = stamina < 0.2 ? 'EXHAUSTED' : 'STAMINA';
    this.els['low-health'].classList.toggle('on', hp > 0 && hp / max <= 0.3);
    this.els['damage-vignette'].style.opacity = String(clamp(1 - hp / max, 0, 0.85));
  }

  setAmmo(mag, reserve, max) {
    if (mag === this.lastAmmo.mag && reserve === this.lastAmmo.reserve) return;
    this.lastAmmo = { mag, reserve, max };
    this.els['ammo-mag'].textContent = mag;
    this.els['ammo-reserve'].textContent = reserve;
    this.els['ammo-mag'].classList.toggle('low', mag <= Math.max(3, Math.floor(max * 0.18)));
  }

  setWeapon(def, mag, reserve) {
    this.els['weapon-name'].textContent = def.name;
    this.els['weapon-mode'].textContent = def.mode;
    this.els['fire-mode'].textContent = def.fireMode;
    this.els['weapon-slot'].textContent = def.slot;
    this.setAmmo(mag, reserve, def.magSize);
  }

  setSpread(px, ads, reloadProgress, reloading) {
    this.els.crosshair.style.setProperty('--spread', `${Math.round(px)}px`);
    this.els.crosshair.style.opacity = ads > 0.7 ? '0.25' : '1';
    const bar = this.els['reload-bar'];
    if (reloading) {
      bar.style.width = `${clamp(reloadProgress, 0, 1) * 100}%`;
      bar.style.background = 'var(--amber)';
    } else {
      bar.style.width = '0%';
    }
  }

  hitmarker(headshot = false) {
    const h = this.els.hitmarker;
    h.classList.remove('show');
    h.classList.toggle('head', headshot);
    void h.offsetWidth;
    h.classList.add('show');
  }

  flashHit() {
    const f = this.els['hit-flash'];
    f.classList.remove('on');
    void f.offsetWidth;
    f.classList.add('on');
  }

  damageDirection(angle, amount) {
    const el = document.createElement('div');
    el.className = 'dmg-dir';
    el.style.setProperty('--rot', `${angle}rad`);
    el.style.opacity = String(clamp(0.4 + amount / 40, 0.4, 1));
    this.els['damage-dirs'].appendChild(el);
    setTimeout(() => el.remove(), 1200);
    this.flashHit();
  }

  killfeed(name, headshot = false) {
    const el = document.createElement('div');
    el.className = 'kill-item';
    el.innerHTML = `YOU <b>›</b> ${name}${headshot ? ' <span class="hs">[HEADSHOT]</span>' : ''}`;
    this.els.killfeed.appendChild(el);
    while (this.els.killfeed.children.length > 5) this.els.killfeed.firstChild.remove();
    setTimeout(() => el.remove(), 4000);
  }

  waveBanner(wave, sub = 'HOSTILES INBOUND') {
    const b = this.els['wave-banner'];
    b.querySelector('.wb-title').textContent = wave === 5 ? 'FINAL WAVE' : `WAVE ${wave}`;
    b.querySelector('.wb-sub').textContent = sub;
    b.querySelector('.wb-kicker').textContent = wave === 5 ? 'WARNING' : 'INCOMING';
    b.classList.remove('show');
    void b.offsetWidth;
    b.classList.add('show');
    clearTimeout(this.waveTimer);
    this.waveTimer = setTimeout(() => b.classList.remove('show'), 3300);
  }

  toast(text, duration = 2200) {
    const t = this.els.toast;
    t.textContent = text;
    t.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => t.classList.remove('show'), duration);
  }

  hint(show) {
    this.els.hint.classList.toggle('hidden', !show);
  }

  updateCompass(yaw) {
    const ctx = this.compassCtx;
    const w = 520, h = 42;
    ctx.clearRect(0, 0, w, h);
    const heading = ((-yaw * 180) / Math.PI + 360) % 360;
    this.els['compass-heading'].textContent = String(Math.round(heading) % 360).padStart(3, '0');
    const pxPerDeg = w / 120;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const labels = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' };
    for (let d = -70; d <= 70; d += 5) {
      const deg = Math.round(heading + d);
      const x = w / 2 + (deg - heading) * pxPerDeg;
      if (x < 0 || x > w) continue;
      const norm = ((deg % 360) + 360) % 360;
      const isMajor = norm % 45 === 0;
      const isMid = norm % 15 === 0;
      ctx.strokeStyle = isMajor ? 'rgba(255,176,46,.9)' : isMid ? 'rgba(255,255,255,.45)' : 'rgba(255,255,255,.2)';
      ctx.lineWidth = isMajor ? 1.6 : 1;
      ctx.beginPath();
      ctx.moveTo(x, h - 4);
      ctx.lineTo(x, h - (isMajor ? 14 : isMid ? 10 : 7));
      ctx.stroke();
      if (isMajor) {
        ctx.fillStyle = norm === 0 ? '#ffb02e' : 'rgba(255,255,255,.8)';
        ctx.font = '600 13px Rajdhani, sans-serif';
        ctx.fillText(labels[norm] || String(norm), x, 13);
      }
    }
  }

  updateMinimap(player, enemies, world, barrels) {
    const ctx = this.minimapCtx;
    const size = 168;
    const c = size / 2;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(c, c, c - 1, 0, Math.PI * 2);
    ctx.clip();
    // background
    const bg = ctx.createRadialGradient(c, c, 10, c, c, c);
    bg.addColorStop(0, 'rgba(14,22,28,.9)');
    bg.addColorStop(1, 'rgba(5,8,11,.95)');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, size, size);
    const scale = 1.55;
    ctx.translate(c, c);
    ctx.rotate(player.yaw);
    // grid
    ctx.strokeStyle = 'rgba(255,255,255,.045)';
    ctx.lineWidth = 1;
    for (let g = -60; g <= 60; g += 15) {
      ctx.beginPath(); ctx.moveTo(g * scale, -90); ctx.lineTo(g * scale, 90); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-90, g * scale); ctx.lineTo(90, g * scale); ctx.stroke();
    }
    // colliders
    for (const b of world.colliders) {
      if (b.maxY < 0.7) continue;
      const x = ((b.minX + b.maxX) / 2 - player.position.x) * scale;
      const z = ((b.minZ + b.maxZ) / 2 - player.position.z) * scale;
      const w = (b.maxX - b.minX) * scale;
      const d = (b.maxZ - b.minZ) * scale;
      if (Math.abs(x) > 130 || Math.abs(z) > 130) continue;
      ctx.fillStyle = b.maxY > 3 ? 'rgba(140,155,165,.28)' : 'rgba(120,135,145,.2)';
      ctx.fillRect(x - w / 2, z - d / 2, w, d);
    }
    // barrels
    for (const b of barrels) {
      if (!b.alive) continue;
      const x = (b.x - player.position.x) * scale;
      const z = (b.z - player.position.z) * scale;
      if (Math.hypot(x, z) > 120) continue;
      ctx.fillStyle = 'rgba(255,140,40,.8)';
      ctx.beginPath(); ctx.arc(x, z, 1.8, 0, Math.PI * 2); ctx.fill();
    }
    // enemies
    for (const e of enemies) {
      if (e.state === 'dead' || e.removed) continue;
      const x = (e.pos.x - player.position.x) * scale;
      const z = (e.pos.z - player.position.z) * scale;
      if (Math.hypot(x, z) > 120) continue;
      const isBoss = e.typeName === 'boss';
      ctx.fillStyle = isBoss ? 'rgba(255,200,60,.95)' : e.typeName === 'rusher' ? 'rgba(255,120,40,.9)' : 'rgba(255,60,45,.9)';
      ctx.beginPath(); ctx.arc(x, z, isBoss ? 4 : 2.6, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(255,60,45,.25)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(x, z, isBoss ? 7 : 5, 0, Math.PI * 2); ctx.stroke();
    }
    // view cone
    ctx.fillStyle = 'rgba(120,230,255,.06)';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(-38, -62);
    ctx.lineTo(38, -62);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // player arrow (always up)
    ctx.save();
    ctx.translate(c, c);
    ctx.fillStyle = '#9fe8ff';
    ctx.beginPath();
    ctx.moveTo(0, -6);
    ctx.lineTo(4.5, 5);
    ctx.lineTo(0, 2.5);
    ctx.lineTo(-4.5, 5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // border ring
    ctx.strokeStyle = 'rgba(255,255,255,.15)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(c, c, c - 1, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,176,46,.3)';
    ctx.beginPath(); ctx.arc(c, c, c - 5, 0, Math.PI * 2); ctx.stroke();
  }

  updatePauseStats(stats, fps) {
    this.els['pause-wave'].textContent = `${stats.wave} / 5`;
    this.els['pause-score'].textContent = formatScore(stats.score);
    this.els['pause-kills'].textContent = stats.kills;
    this.els['pause-acc'].textContent = `${stats.accuracy}%`;
    this.els['pause-fps'].textContent = `${fps} FPS`;
  }

  updateRotateNotice() {
    const portrait = window.innerHeight > window.innerWidth && this.isTouch;
    this.els['rotate-notice'].classList.toggle('hidden', !portrait);
  }
}

