const WAVES = [
  [['grunt', 4]],
  [['grunt', 6], ['rusher', 2]],
  [['grunt', 7], ['rusher', 3], ['heavy', 1]],
  [['grunt', 9], ['rusher', 4], ['heavy', 2]],
